]$subjects$::jsonb;
  v_left_out constant jsonb := $left$[
  {"slug":"tws","reason":"no photo found"}
]$left$::jsonb;
  v_checked constant date := date '2026-11-13';
  v_cutoff constant date := (current_date - interval '18 years')::date;
  v_debut_col text;
  v_debut_expr text;
  v_keep jsonb;
  v_gone text[];
  v_summary jsonb;
  sj record;
  g record;
  i record;
  lg record;
  r record;
  e jsonb;
  ph jsonb;
  k jsonb;
  v_slug text;
  v_kind text;
  v_ent text;
  v_reason text;
  v_n integer;
  v_known integer;
  v_adult integer;
  v_year integer;
  v_name text;
  v_section text;
  v_group_ent text;
  v_qid text;
  v_in jsonb := '[]'::jsonb;
  v_out jsonb := '[]'::jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_status text;
  v_kept_files integer := 0;
  v_kept_approved integer := 0;
  v_dropped integer := 0;
  v_closed integer;
  v_max integer;
  v_count integer;
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'notice', true);

  if to_regclass('public.cards_catalog') is null or to_regclass('public.cards_photos') is null or to_regclass('public.cards_entities') is null
     or to_regclass('public.cards_owned') is null or to_regclass('public.cards_packs') is null or to_regclass('public.cards_reports') is null then
    raise exception '103-catalog-photos: the cards tables are missing (run 001 to 003 first)';
  end if;
  if to_regclass('public.groups') is null or to_regclass('public.idols') is null then
    raise exception '103-catalog-photos: public.groups or public.idols is missing';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_catalog' and column_name = 'part') then
    raise exception '103-catalog-photos: cards_catalog has no part column (apply 102-catalog-rebuild.sql first)';
  end if;

  -- The guard: the numbers change, so only while no player holds anything.
  if exists (select 1 from public.cards_owned) then
    raise exception '103-catalog-photos: a player owns a card (cards_owned is not empty), nothing changed';
  end if;
  if exists (select 1 from public.cards_packs) then
    raise exception '103-catalog-photos: a pack was opened (cards_packs is not empty), nothing changed';
  end if;
  if exists (select 1 from public.cards_reports where status = 'open') then
    raise exception '103-catalog-photos: a photo report is open (cards_reports), close it in the admin first, nothing changed';
  end if;
  select count(*) into v_closed from public.cards_reports where photo_id is not null;

  -- 1. The columns of the photos (idempotent).
  alter table public.cards_photos drop constraint if exists cards_photos_slot_check;
  alter table public.cards_photos add constraint cards_photos_slot_check check (slot between 1 and 6);
  alter table public.cards_photos add column if not exists sha1 text;
  alter table public.cards_photos add column if not exists quality smallint;
  alter table public.cards_photos add column if not exists stage boolean not null default false;
  alter table public.cards_photos add column if not exists event_date_precision text;
  alter table public.cards_photos add column if not exists news_only boolean not null default false;
  if not exists (select 1 from pg_constraint where conname = 'cards_photos_quality_check' and conrelid = 'public.cards_photos'::regclass) then
    alter table public.cards_photos add constraint cards_photos_quality_check check (quality is null or quality between 1 and 5);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cards_photos_event_date_precision_check' and conrelid = 'public.cards_photos'::regclass) then
    alter table public.cards_photos add constraint cards_photos_event_date_precision_check check (event_date_precision is null or event_date_precision in ('day', 'month'));
  end if;

  -- 2. What the owner set, by source page: the focal point, the published files, an approval. A refused or removed photo stays out.
  select coalesce(jsonb_object_agg(p.source_page, jsonb_build_object(
           'focal_x', p.focal_x, 'focal_y', p.focal_y, 'storage_path', p.storage_path, 'file_focal_x', p.file_focal_x,
           'file_focal_y', p.file_focal_y, 'status', p.status)), '{}'::jsonb)
    into v_keep
    from public.cards_photos p
   where p.status in ('auto', 'approved', 'pending');
  select coalesce(array_agg(distinct p.source_page), '{}') into v_gone
    from public.cards_photos p
   where p.status in ('rejected', 'removed')
     and not exists (select 1 from public.cards_photos q where q.source_page = p.source_page and q.status in ('auto', 'approved'));

  -- 3. Empty the three tables (cards_owned and cards_packs are empty, checked above).
  delete from public.cards_catalog;
  delete from public.cards_photos;
  delete from public.cards_entities;

  -- The debut year of a group, from the database: a debut column when groups has one, else the year of inception_date (as 101 and 102).
  select column_name into v_debut_col from information_schema.columns
    where table_schema = 'public' and table_name = 'groups' and column_name in ('debut_year', 'debut_date')
    order by (column_name = 'debut_year') desc limit 1;
  v_debut_expr := case v_debut_col
    when 'debut_year' then 'debut_year::integer'
    when 'debut_date' then 'extract(year from debut_date)::integer'
    else 'extract(year from inception_date)::integer' end;

  -- 4. Resolve every subject, exactly as 102: in (with its fields) or out (with the reason).
  for sj in select x.value as v from jsonb_array_elements(v_subjects) x loop
    v_slug := sj.v ->> 'slug';
    v_kind := sj.v ->> 'kind';
    v_ent := case when v_kind = 'group' then 'group:' else 'idol:' end || v_slug;
    v_reason := null;
    v_qid := null;
    g := null; i := null; lg := null;
    select x.id, x.name, x.group_id, x.birth_date, x.wikidata_qid into i from public.idols x where false;

    select gr.id, gr.name, gr.slug into g from public.groups gr where gr.slug = v_slug;
    if g.id is null then
      v_reason := 'no_groups_row';
    elsif v_kind = 'group' then
      -- A disbanded group has no active member: every row of the group is read (its former members); any other group, its active rows.
      select count(*), count(x.birth_date), count(*) filter (where x.birth_date <= v_cutoff)
        into v_n, v_known, v_adult from public.idols x
       where x.group_id = g.id and (x.active or (sj.v ->> 'end_year') is not null);
      if v_n = 0 then v_reason := case when (sj.v ->> 'end_year') is not null then 'no_member' else 'no_active_member' end;
      elsif v_known < v_n then v_reason := 'unknown_birth_date';
      elsif v_adult < v_n then v_reason := 'minor_member';
      end if;
    else
      select count(*) into v_n from public.idols x where x.group_id = g.id and x.active;
      if v_n = 0 then
        select count(*) into v_n from public.idols x where x.group_id <> g.id and x.active and lower(btrim(x.name)) = lower(btrim(g.name));
        if v_n = 1 then
          select x.id, x.name, x.group_id, x.birth_date, x.wikidata_qid into i
            from public.idols x where x.group_id <> g.id and x.active and lower(btrim(x.name)) = lower(btrim(g.name));
        end if;
      elsif v_n = 1 then
        select x.id, x.name, x.group_id, x.birth_date, x.wikidata_qid into i
          from public.idols x where x.group_id = g.id and x.active;
      end if;
      if v_n > 1 then v_reason := 'ambiguous';
      elsif i.id is null then v_reason := 'no_idol_row';
      elsif i.birth_date is null then v_reason := 'unknown_birth_date';
      elsif i.birth_date > v_cutoff then v_reason := 'minor';
      end if;
    end if;

    if v_reason is not null then
      v_out := v_out || jsonb_build_array(jsonb_build_object('slug', v_slug, 'reason', v_reason));
      continue;
    end if;

    v_group_ent := null;
    if v_kind = 'group' then
      v_name := g.name;
      v_section := g.name;
      execute format('select %s from public.groups where id = $1', v_debut_expr) into v_year using g.id;
    else
      v_name := coalesce(nullif(btrim(i.name), ''), g.name);
      v_qid := nullif(btrim(i.wikidata_qid), '');
      if i.group_id <> g.id then
        select gr.id, gr.name, gr.slug into lg from public.groups gr where gr.id = i.group_id;
        v_section := lg.name;
        v_group_ent := 'group:' || lg.slug;
        execute format('select %s from public.groups where id = $1', v_debut_expr) into v_year using lg.id;
        v_lines := v_lines || jsonb_build_array(jsonb_build_object('id', v_group_ent, 'name', lg.name, 'debut_year', v_year));
      else
        v_section := v_name;
        execute format('select %s from public.groups where id = $1', v_debut_expr) into v_year using g.id;
      end if;
    end if;

    v_in := v_in || jsonb_build_array(sj.v || jsonb_build_object(
      'entity', v_ent, 'name', v_name, 'section', v_section, 'group_entity', v_group_ent, 'debut_year', v_year, 'qid', v_qid));
  end loop;

  -- 5. Entities (decision 2 order: section A to Z, the people of a section before its group, then the name): the subjects, the group lines
  --    of the people (no cards of their own). A group line that is also a subject is the subject's row. lock_reasons and active are set by
  --    cards_build_catalog below.
  insert into public.cards_entities (id, kind, name, group_id, debut_year, qid, sort_key, lock_reasons, active, end_year)
  select x ->> 'entity', 'group', x ->> 'name', null, nullif(x ->> 'debut_year', '')::integer, null,
         lower(x ->> 'section') || '|1|' || lower(x ->> 'name'), '{}'::jsonb, true, nullif(x ->> 'end_year', '')::integer
    from jsonb_array_elements(v_in) x where x ->> 'kind' = 'group';
  insert into public.cards_entities (id, kind, name, group_id, debut_year, qid, sort_key, lock_reasons, active)
  select distinct on (l ->> 'id') l ->> 'id', 'group', l ->> 'name', null, nullif(l ->> 'debut_year', '')::integer, null,
         lower(l ->> 'name') || '|1|' || lower(l ->> 'name'), '{}'::jsonb, true
    from jsonb_array_elements(v_lines) l
  on conflict (id) do nothing;
  insert into public.cards_entities (id, kind, name, group_id, debut_year, qid, sort_key, lock_reasons, active)
  select x ->> 'entity', 'idol', x ->> 'name', x ->> 'group_entity', nullif(x ->> 'debut_year', '')::integer, x ->> 'qid',
         lower(x ->> 'section') || '|0|' || lower(x ->> 'name'), '{}'::jsonb, true
    from jsonb_array_elements(v_in) x where x ->> 'kind' = 'idol';

  -- 6. The photos of the subjects in, with what the owner set (focal point, files, approval).
  for e in select x.value from jsonb_array_elements(v_in) x loop
    for ph in select y.value from jsonb_array_elements(e -> 'photos') y loop
      if (ph ->> 'page') = any (v_gone) then
        v_dropped := v_dropped + 1;
        continue;
      end if;
      k := v_keep -> (ph ->> 'page');
      v_status := case when k ->> 'status' = 'approved' then 'approved' else ph ->> 'status' end;
      if k ->> 'status' = 'approved' and ph ->> 'status' = 'pending' then v_kept_approved := v_kept_approved + 1; end if;
      if k ->> 'storage_path' is not null then v_kept_files := v_kept_files + 1; end if;
      insert into public.cards_photos (entity_id, slot, source, source_page, file_url, author, author_url, licence, licence_url, share_alike,
                                       checked_at, event_name, event_date, event_date_precision, focal_x, focal_y, source_path, source_width,
                                       source_height, small_2x, storage_path, file_focal_x, file_focal_y, status, review_note, sha1, quality,
                                       stage, news_only)
      values (e ->> 'entity', (ph ->> 'slot')::integer, ph ->> 'source', ph ->> 'page', ph ->> 'url', ph ->> 'author', ph ->> 'author_url',
              ph ->> 'licence', ph ->> 'licence_url', (ph ->> 'share_alike')::boolean, v_checked, ph ->> 'event',
              case when ph ->> 'date_precision' = 'month' then (ph ->> 'date' || '-01')::date else (ph ->> 'date')::date end,
              ph ->> 'date_precision',
              coalesce((k ->> 'focal_x')::integer, (ph ->> 'fx')::integer), coalesce((k ->> 'focal_y')::integer, (ph ->> 'fy')::integer),
              ph ->> 'source_path', (ph ->> 'width')::integer, (ph ->> 'height')::integer,
              -- the photo's own flag (the admin's 2x list): a person's window, or either half of a group's pair, under 640 px
              case when e ->> 'kind' = 'group'
                   then floor(least((ph ->> 'width')::numeric, (ph ->> 'height')::numeric * 11 / 8.5))::integer / 2 < 640
                   else floor(least((ph ->> 'width')::numeric, (ph ->> 'height')::numeric * 5.5 / 8.5))::integer < 640 end,
              k ->> 'storage_path', (k ->> 'file_focal_x')::integer, (k ->> 'file_focal_y')::integer,
              v_status,
              case when v_status = 'pending' then 'To review: ' || (ph ->> 'review')
                   when v_status = 'approved' and ph ->> 'status' = 'pending' then 'Approved by the owner in the admin.'
                   when (ph ->> 'slot')::integer = 1 and ph ->> 'status' = 'approved' then 'Commons photo of the October 2026 run, checked by eye (amendment 1); age rule of lot 2 passed on its date.'
                   else 'Commons licence, author, file and deletion requests checked by verify-photos.mts on ' || v_checked || '; age rule passed on its date.' end,
              ph ->> 'sha1', (ph ->> 'quality')::smallint, (ph ->> 'stage')::boolean, (ph ->> 'news_only')::boolean);
    end loop;
  end loop;

  -- 7. The edition rule, in one place (the admin runs it again after the owner's review).
  create or replace function public.cards_build_catalog()
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    c_ladder constant text[] := array['C', 'U', 'R', 'SR', 'UR', 'L'];
    c_edition constant jsonb := '{"C": "std", "U": "stage", "R": "holo", "SR": "era", "UR": "gold", "L": "full"}'::jsonb;
    e record;
    v_ids bigint[];
    v_full boolean[];
    v_stage boolean[];
    v_cw integer[];
    v_shown boolean[];
    v_open text[];
    v_pick jsonb;
    v_used bigint[];
    v_lock jsonb;
    v_old jsonb;
    v_n integer;
    v_i integer;
    v_j integer;
    v_r text;
    v_id bigint;
    v_cwi integer;
    v_no integer := 0;
    v_subjects integer := 0;
    v_waiting integer := 0;
  begin
    if exists (select 1 from public.cards_owned) then
      raise exception 'cards_build_catalog: a player owns a card, the catalog numbers cannot change';
    end if;
    if exists (select 1 from public.cards_packs) then
      raise exception 'cards_build_catalog: a pack was opened, the catalog numbers cannot change';
    end if;
    delete from public.cards_catalog;
    for e in select en.id, en.kind, en.lock_reasons from public.cards_entities en
              where en.kind in ('idol', 'group') and exists (select 1 from public.cards_photos p where p.entity_id = en.id)
              order by en.sort_key, en.id loop
      -- The live photos, best first: the researcher's quality, then the pixels of the crop window, then the most recent, then the slot.
      select array_agg(x.id order by x.rk), array_agg(x.full_ok order by x.rk), array_agg(x.stage order by x.rk),
             array_agg(x.cw order by x.rk), array_agg(x.shown order by x.rk)
        into v_ids, v_full, v_stage, v_cw, v_shown
        from (select p.id, p.stage, w.cw,
                     case when e.kind = 'group' then w.cw / 2 >= 640 else w.cw >= 640 end as full_ok,
                     (p.storage_path is not null or p.source_path is not null) as shown,
                     row_number() over (order by coalesce(p.quality, 3) desc, w.cw desc, p.event_date desc nulls last, p.slot) as rk
                from public.cards_photos p
                cross join lateral (select floor(least(p.source_width::numeric,
                                      p.source_height::numeric * (case when e.kind = 'group' then 11 else 5.5 end) / 8.5))::integer as cw) w
               where p.entity_id = e.id and p.status in ('auto', 'approved')
                 and p.source_width is not null and p.source_height is not null) x;
      v_n := least(coalesce(cardinality(v_ids), 0), 6);
      if v_n < 2 then
        -- One approved photo (or none yet): no edition, the subject waits for a second photo (owner decision: packs from 2 photos).
        update public.cards_entities set active = false, lock_reasons = '{}'::jsonb where id = e.id;
        v_waiting := v_waiting + 1;
        continue;
      end if;
      v_open := c_ladder[1:v_n];
      v_pick := '{}'::jsonb;
      v_used := '{}';
      v_lock := '{}'::jsonb;
      -- Full Art: the best photo that gives an honest 2x of the whole card; none, and Full Art stays locked.
      if 'L' = any (v_open) then
        v_id := null;
        for v_i in 1 .. cardinality(v_ids) loop
          if v_full[v_i] then v_id := v_ids[v_i]; exit; end if;
        end loop;
        if v_id is null then
          v_open := array_remove(v_open, 'L');
          v_lock := v_lock || '{"L": "size"}'::jsonb;
        else
          v_pick := v_pick || jsonb_build_object('L', v_id);
          v_used := v_used || v_id;
        end if;
      end if;
      -- Stage: a stage photo when there is one, the lowest rated, so the best photos stay on the higher editions.
      if 'U' = any (v_open) then
        v_id := null;
        for v_i in reverse cardinality(v_ids) .. 1 loop
          if v_stage[v_i] and not (v_ids[v_i] = any (v_used)) then v_id := v_ids[v_i]; exit; end if;
        end loop;
        if v_id is not null then
          v_pick := v_pick || jsonb_build_object('U', v_id);
          v_used := v_used || v_id;
        end if;
      end if;
      -- The other editions, from the highest down, take the remaining photos best first.
      for v_i in reverse cardinality(v_open) .. 1 loop
        v_r := v_open[v_i];
        continue when v_pick ->> v_r is not null;
        v_id := null;
        for v_j in 1 .. cardinality(v_ids) loop
          if not (v_ids[v_j] = any (v_used)) then v_id := v_ids[v_j]; exit; end if;
        end loop;
        v_pick := v_pick || jsonb_build_object(v_r, v_id);
        v_used := v_used || v_id;
      end loop;
      -- Why an edition is missing: no photo for it yet, or (Full Art) no photo large enough; an owner's 'hiatus' stays.
      v_old := coalesce(e.lock_reasons, '{}'::jsonb);
      foreach v_r in array c_ladder loop
        if not (v_r = any (v_open)) then
          v_lock := v_lock || jsonb_build_object(v_r, case when v_old ->> v_r = 'hiatus' then 'hiatus' else coalesce(v_lock ->> v_r, 'photo') end);
        end if;
      end loop;
      -- The cards, in ladder order; a group gives a pair with consecutive numbers.
      foreach v_r in array v_open loop
        v_id := (v_pick ->> v_r)::bigint;
        v_i := array_position(v_ids, v_id);
        v_cwi := v_cw[v_i];
        if e.kind = 'group' then
          insert into public.cards_catalog (card_no, num, entity_id, rarity, edition, photo_id, in_packs, part, small_2x)
          values (v_no + 1, 'BV1-' || lpad((v_no + 1)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 1, v_cwi / 2 < 640),
                 (v_no + 2, 'BV1-' || lpad((v_no + 2)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 2, (v_cwi - v_cwi / 2) < 640);
          v_no := v_no + 2;
        else
          insert into public.cards_catalog (card_no, num, entity_id, rarity, edition, photo_id, in_packs, part, small_2x)
          values (v_no + 1, 'BV1-' || lpad((v_no + 1)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 0, v_cwi < 640);
          v_no := v_no + 1;
        end if;
      end loop;
      update public.cards_entities set active = true, lock_reasons = v_lock where id = e.id;
      v_subjects := v_subjects + 1;
    end loop;
    return jsonb_build_object('subjects', v_subjects, 'waiting', v_waiting, 'cards', v_no,
      'by_rarity', coalesce((select jsonb_object_agg(x.rarity, x.n) from (select rarity, count(*) as n from public.cards_catalog group by rarity) x), '{}'::jsonb),
      'not_shown', (select count(*) from public.cards_catalog where not in_packs));
  end
  $f$;

  -- 8. A card is in the packs only while its photo is live and has something to show (the owner's cut files, or the lot 1 bucket copy):
  --    a photo cut by the owner's script after this file enters the packs then; a refused or removed one leaves them (as cards_photo_retire).
  create or replace function public.cards_photo_ready()
    returns trigger
    language plpgsql security definer set search_path = public
    as $f$
  begin
    update public.cards_catalog c
       set in_packs = (new.status in ('auto', 'approved') and (new.storage_path is not null or new.source_path is not null))
     where c.photo_id = new.id
       and c.in_packs is distinct from (new.status in ('auto', 'approved') and (new.storage_path is not null or new.source_path is not null));
    return new;
  end
  $f$;
  drop trigger if exists cards_photos_ready on public.cards_photos;
  create trigger cards_photos_ready after update of status, storage_path, source_path on public.cards_photos
    for each row execute function public.cards_photo_ready();

  revoke all on function public.cards_build_catalog() from public, anon, authenticated;
  revoke all on function public.cards_photo_ready() from public, anon, authenticated;
  grant execute on function public.cards_build_catalog() to service_role;
  grant execute on function public.cards_photo_ready() to service_role;

  v_summary := public.cards_build_catalog();

  -- 9. Checks, then the Verify output.
  select coalesce(max(card_no), 0), count(*) into v_max, v_count from public.cards_catalog;
  if v_max <> v_count then
    raise exception '103-catalog-photos: the numbers are not contiguous (highest %, % cards)', v_max, v_count;
  end if;
  if exists (select 1 from public.cards_catalog group by entity_id, photo_id having count(distinct rarity) > 1) then
    raise exception '103-catalog-photos: a photo is on two editions';
  end if;
  if exists (select 1 from public.cards_catalog a join public.cards_catalog b on b.entity_id = a.entity_id and b.rarity = a.rarity and b.part = 2
             where a.part = 1 and b.card_no <> a.card_no + 1) then
    raise exception '103-catalog-photos: a pair does not have consecutive numbers';
  end if;
  raise notice '103-catalog-photos: % subjects in the packs, % waiting for a second approved photo, % cards, highest number BV1-%',
    v_summary ->> 'subjects', v_summary ->> 'waiting', v_count, lpad(v_max::text, 4, '0');
  for r in select c.rarity, count(*) as n, count(distinct c.entity_id) as s from public.cards_catalog c
            group by c.rarity order by array_position(array['C', 'U', 'R', 'SR', 'UR', 'L'], c.rarity) loop
    raise notice '103-catalog-photos: edition % has % cards (% subjects)', r.rarity, r.n, r.s;
  end loop;
  for r in select p.status, count(*) as n from public.cards_photos p group by p.status order by p.status loop
    raise notice '103-catalog-photos: photos % %', r.status, r.n;
  end loop;
  raise notice '103-catalog-photos: % cards wait for their files (publish-card-files.mjs --publish), % photos kept their published files, % approvals of the owner kept, % photos left out because the owner refused or removed them',
    v_summary ->> 'not_shown', v_kept_files, v_kept_approved, v_dropped;
  for r in select x.value ->> 'slug' as slug, x.value ->> 'end_year' as y from jsonb_array_elements(v_in) x where x.value ->> 'end_year' is not null order by 1 loop
    raise notice '103-catalog-photos: % is in as a disbanded group (%)', r.slug, r.y;
  end loop;
  for r in select x.value ->> 'slug' as slug, x.value ->> 'reason' as reason from jsonb_array_elements(v_left_out) x loop
    raise notice '103-catalog-photos: left out % (%)', r.slug, r.reason;
  end loop;
  for r in select x.value ->> 'slug' as slug, x.value ->> 'reason' as reason from jsonb_array_elements(v_out) x loop
    raise notice '103-catalog-photos: left out % (%)', r.slug, r.reason;
  end loop;
  if v_closed > 0 then
    raise notice '103-catalog-photos: % closed photo reports lost their photo link (the photo rows were rebuilt)', v_closed;
  end if;
  if (select count(*) from public.cards_entities where id in (select 'idol:' || s from unnest(array['bibi', 'chungha', 'heize', 'hwasa', 'hyuna', 'iu', 'jay-park', 'jennie', 'jeon-somi', 'jimin', 'jungkook', 'psy', 'rose', 'sunmi', 'taeyang', 'taeyeon', 'v-bts', 'zico', 'akmu', 'apink', 'artms', 'astro', 'billlie', 'btob', 'day6', 'dreamcatcher', 'fifty-fifty', 'fromis-9', 'ikon', 'illit', 'kara', 'katseye', 'kiss-of-life', 'loona', 'loossemble', 'miss-a', 'monsta-x', 'nct', 'nct-wish', 'p1harmony', 'pentagon', 'purple-kiss', 'sistar', 'stayc', 't-ara', 'viviz', 'winner', 'zerobaseone']) s union all select 'group:' || s from unnest(array['bibi', 'chungha', 'heize', 'hwasa', 'hyuna', 'iu', 'jay-park', 'jennie', 'jeon-somi', 'jimin', 'jungkook', 'psy', 'rose', 'sunmi', 'taeyang', 'taeyeon', 'v-bts', 'zico', 'akmu', 'apink', 'artms', 'astro', 'billlie', 'btob', 'day6', 'dreamcatcher', 'fifty-fifty', 'fromis-9', 'ikon', 'illit', 'kara', 'katseye', 'kiss-of-life', 'loona', 'loossemble', 'miss-a', 'monsta-x', 'nct', 'nct-wish', 'p1harmony', 'pentagon', 'purple-kiss', 'sistar', 'stayc', 't-ara', 'viviz', 'winner', 'zerobaseone']) s)) = 0 then
    raise notice '103-catalog-photos: no subject resolved (public.groups has none of the slugs)';
  end if;
end $c103$;

-- ==== 5/15: 104-economy.sql (verbatim) ====
-- 104-economy.sql (Bunnyverse Cards lots 3 and 4, lane ECON, 2026-11-13; the Gold guarantee, the timer cap, crafting, the wishlist, the focus pack, the ad shards, the moment)
--
-- What:   adds the database side of the economy rules, in ONE DO block:
--           tables   cards_crafts      the ledger of crafts (who crafted which card, for how many shards, when)
--                    cards_wishlist    the cards a player wants (at most 50 each)
--           columns  cards_wallets.timer_today   refills the timer added since Paris midnight (the midnight top-up is not counted)
--                    cards_packs.focus           the group (cards_entities.id) a focus pack was opened for, null for every other pack
--                    cards_packs.new_count       the cards new to the player in that pack (filled for new packs only, never backfilled)
--                    cards_owned.first_pack_no   the player's pack count when the card first came, that pack included (new pulls and crafts only)
--                    cards_owned.first_source    'pack', 'craft' or 'demo' (new pulls, crafts and demo claims only, never backfilled)
--           new functions
--                    cards_pity_count(user)               packs in a row, newest first, with no Gold and no Full Art card (0 to 30)
--                    cards_pity_pool()                    true while a Gold card is in packs (the guarantee needs one)
--                    cards_focus_used(user, now)          true when a focus pack was opened on the Paris day of now
--                    cards_craft(user, card_no, now)      spends the shards of the card's rarity and stores the card, one transaction
--                    cards_wish(user, card_no, on, now)   adds or removes a card of the wishlist
--                    cards_ad_grant(user, ticket, now, ads_limit, shards, timer_cap)   spends a ticket, counts the ad, gives shards
--                    cards_recent_packs(user, limit)      the last packs: opened_at, best rarity, source, new_count
--           replaced functions (the old signature is dropped and the new one created in the same block: exactly one of each name exists)
--                    cards_roll(..., timer, timer_cap)    the refill, now with the day's timer count and its cap (returns timer_today)
--                    cards_wallet(user, now, ads_limit, bonus_cap, timer_cap)   adds timer_used, timer_cap, timer_left, pity_left, focus_used
--                    cards_apply_pack(user, source, cards, ticket, now, ads_limit, bonus_cap, timer_cap, focus)   adds the Gold guarantee
--                      (raise 'cards: pity'), the focus pack (raise 'cards: focus', 'cards: focus_used'), the pair mark (completesPair), the
--                      moment columns, the wishlist cleanup; refuses a new 'ad' pack (raise 'cards: source')
-- Why:    the owner's rules of lots 3 and 4: a Gold card at the latest in the 30th pack without a Gold or a Full Art; at most 40 packs a Paris
--         day from the timer (CARDS_TIMER_PER_DAY overrides it on the server); a missing card can be crafted with shards (never a Full Art); a
--         wishlist and, once a Paris day, a focus pack whose cards 2 and 4 come from a group the player picks; a rewarded ad gives 25 shards
--         (CARDS_AD_SHARDS) and not a pack; the moment screen needs the pack number of a card and the new cards of a pack. The draw stays in
--         TypeScript (lib/cards/rules.ts); the database refuses a pack that breaks a promise, so no server bug can break it.
-- Rows:   0 rows. 2 tables, 5 columns, 7 new functions, 3 functions replaced (cards_issue_ticket is untouched). Additive: no existing table is
--         dropped, no row is changed. No XP, level, streak or badge is read or written.
-- Needs:  001 and 002 (and 003 for the grants of the older tables), and 102 for cards_catalog.part (the pair mark). Not 103.
-- Notes:  the Gold count looks at the last 30 packs of the player, any source, newest first: a pack that holds a Gold or a Full Art card ends
--         the count. From 29 packs without one, the next pack must have a Gold card as its 5th card, only while the pool has a Gold card
--         (cards_pity_pool). The timer cap counts the refills of the Paris day in the wallet row (timer_today), computed by cards_roll: a
--         refill adds a pack only while fewer than the cap were added since Paris midnight; at the cap the stack adds nothing until
--         midnight, and a pack already in the stack always opens (no refusal at opening). The midnight top-up does not count. A craft costs
--         Standard 10, Stage 20, Holo 50, Era 120, Gold 300 (CRAFT_COST in rules.ts) and a Full Art cannot be crafted. A focus pack is a pack
--         of source 'stock' (a pack of the stack), once a Paris day, and card 2 and card 4 come from the group (its own cards and those of its
--         idols) unless the group has no card of their rarity. The pair mark: a new card whose other half (same subject, same rarity, the other
--         part) the player already owns, in an earlier pack or earlier in this pack. An ad pack can no longer be opened: cards_ad_grant gives
--         shards (the value 'ad' stays allowed in cards_packs.source for the history).
-- Errors: a refusal is an exception whose message starts with 'cards: ' and one word. New words: pity, focus, focus_used, owned, card,
--         no_craft, wish_limit (and the older shards, pack, source, ticket, ad_limit, empty, bonus).
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_pity_count', 'cards_pity_pool', 'cards_focus_used', 'cards_craft', 'cards_wish', 'cards_ad_grant', 'cards_recent_packs');   expect 7
-- Verify: select proname, count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_roll', 'cards_wallet', 'cards_apply_pack') group by proname order by proname;   expect cards_apply_pack 1, cards_roll 1, cards_wallet 1
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_%';   expect f
-- Verify: select count(*) from pg_tables where schemaname = 'public' and tablename in ('cards_crafts', 'cards_wishlist') and rowsecurity;   expect 2
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_crafts', 'cards_wishlist') and grantee in ('anon', 'authenticated');   expect 0
-- Verify: select count(*) from information_schema.columns where table_schema = 'public' and ((table_name = 'cards_wallets' and column_name = 'timer_today') or (table_name = 'cards_packs' and column_name in ('focus', 'new_count')) or (table_name = 'cards_owned' and column_name in ('first_pack_no', 'first_source')));   expect 5
-- Verify: select (public.cards_wallet('00000000-0000-0000-0000-000000000000', '2026-11-12 10:00+00')) ->> 'timer_left';   expect 40
-- Verify: select (public.cards_wallet('00000000-0000-0000-0000-000000000000', '2026-11-12 10:00+00')) ->> 'pity_left';   expect 30 once a Gold card is in packs (empty before)
-- Verify: select count(*) from public.cards_owned where first_pack_no is not null or first_source is not null;   expect 0 right after the first run (nothing is backfilled)
-- Undo:   104-economy.rollback.sql (restores the functions of 002; refused while a craft is recorded)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c104$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_wallets') is null or to_regclass('public.cards_catalog') is null or to_regclass('public.cards_packs') is null
     or to_regclass('public.cards_owned') is null or to_regclass('public.cards_entities') is null then
    raise exception '104-economy: run 001-schema.sql first';
  end if;
  if to_regprocedure('public.cards_bonus_plays(uuid, date)') is null
     or (to_regprocedure('public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz)') is null
         and to_regprocedure('public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer)') is null) then
    raise exception '104-economy: run 002-functions.sql first';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_catalog' and column_name = 'part') then
    raise exception '104-economy: run 102-catalog-rebuild.sql first (cards_catalog.part)';
  end if;

  -- The ledger of crafts. No foreign key on the card: a catalog rebuild must not erase what a player spent.
  create table if not exists public.cards_crafts (
    id bigint generated always as identity constraint cards_crafts_pkey primary key,
    user_id uuid not null constraint cards_crafts_user_id_fkey references auth.users(id) on delete cascade,
    card_no integer not null,
    rarity text not null constraint cards_crafts_rarity_check check (rarity in ('C', 'U', 'R', 'SR', 'UR')),
    cost integer not null constraint cards_crafts_cost_check check (cost > 0),
    crafted_at timestamptz not null default now()
  );
  alter table public.cards_crafts enable row level security;
  revoke all on table public.cards_crafts from public, anon, authenticated;
  grant all on table public.cards_crafts to service_role;
  create index if not exists cards_crafts_user_idx on public.cards_crafts (user_id, crafted_at desc);

  create table if not exists public.cards_wishlist (
    user_id uuid not null constraint cards_wishlist_user_id_fkey references auth.users(id) on delete cascade,
    card_no integer not null constraint cards_wishlist_card_no_fkey references public.cards_catalog(card_no) on delete cascade,
    added_at timestamptz not null default now(),
    constraint cards_wishlist_pkey primary key (user_id, card_no)
  );
  alter table public.cards_wishlist enable row level security;
  revoke all on table public.cards_wishlist from public, anon, authenticated;
  grant all on table public.cards_wishlist to service_role;

  -- The day's timer refills, on the wallet row (reset by cards_roll at Paris midnight).
  alter table public.cards_wallets add column if not exists timer_today integer not null default 0;
  if not exists (select 1 from pg_constraint where conname = 'cards_wallets_timer_today_check' and conrelid = 'public.cards_wallets'::regclass) then
    alter table public.cards_wallets add constraint cards_wallets_timer_today_check check (timer_today >= 0);
  end if;

  alter table public.cards_packs add column if not exists focus text;
  if not exists (select 1 from pg_constraint where conname = 'cards_packs_focus_fkey' and conrelid = 'public.cards_packs'::regclass) then
    alter table public.cards_packs add constraint cards_packs_focus_fkey foreign key (focus) references public.cards_entities(id) on delete set null;
  end if;
  create index if not exists cards_packs_focus_idx on public.cards_packs (user_id, opened_at desc) where focus is not null;

  -- The moment: the cards new to the player in a pack, and the pack number / source of the first copy of a card. Null on every older row.
  alter table public.cards_packs add column if not exists new_count integer;
  if not exists (select 1 from pg_constraint where conname = 'cards_packs_new_count_check' and conrelid = 'public.cards_packs'::regclass) then
    alter table public.cards_packs add constraint cards_packs_new_count_check check (new_count is null or new_count between 0 and 5);
  end if;
  alter table public.cards_owned add column if not exists first_pack_no integer;
  alter table public.cards_owned add column if not exists first_source text;
  if not exists (select 1 from pg_constraint where conname = 'cards_owned_first_pack_no_check' and conrelid = 'public.cards_owned'::regclass) then
    alter table public.cards_owned add constraint cards_owned_first_pack_no_check check (first_pack_no is null or first_pack_no >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cards_owned_first_source_check' and conrelid = 'public.cards_owned'::regclass) then
    alter table public.cards_owned add constraint cards_owned_first_source_check check (first_source is null or first_source in ('pack', 'craft', 'demo'));
  end if;

  -- The refill and the Paris midnight on a row, as jsonb {stock, anchor, paris_day, ads_today, bonus_today, timer_today}. Not exposed.
  -- Lot 3 A13: a refill adds a pack only while fewer than p_timer_cap were added since Paris midnight; at the cap the stack adds nothing (its
  -- anchor stays where it is) until midnight. The midnight top-up to 5 is not a refill and is not counted.
  drop function if exists public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz);
  create or replace function public.cards_roll(
      p_stock integer, p_anchor timestamptz, p_day date, p_ads integer, p_bonus integer, p_now timestamptz,
      p_timer integer default 0, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql stable set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_stock integer := p_stock;
    v_anchor timestamptz := p_anchor;
    v_ads integer := p_ads;
    v_bonus integer := p_bonus;
    v_timer integer := coalesce(p_timer, 0);
    k bigint;
    g integer;
    v_room integer;
  begin
    if p_day is distinct from v_today then
      v_ads := 0;
      v_bonus := 0;
      v_timer := 0;
      if v_stock < 5 then
        v_stock := 5;
        v_anchor := p_now;
      end if;
    end if;
    if v_stock >= 5 then
      v_anchor := p_now;
    else
      k := floor(extract(epoch from (p_now - v_anchor)) / 600);
      v_room := greatest(0, p_timer_cap - v_timer);
      if k > 0 and v_room > 0 then
        g := least(k, 5 - v_stock, v_room);
        v_stock := v_stock + g;
        v_timer := v_timer + g;
        if v_stock >= 5 then
          v_anchor := p_now;
        elsif g = v_room then
          v_anchor := v_anchor + make_interval(secs => (g * 600)::double precision);
        else
          v_anchor := v_anchor + make_interval(secs => (k * 600)::double precision);
        end if;
      end if;
    end if;
    return jsonb_build_object('stock', v_stock, 'anchor', v_anchor, 'paris_day', v_today, 'ads_today', v_ads, 'bonus_today', v_bonus, 'timer_today', v_timer);
  end
  $f$;

  -- Packs in a row, newest first, that held no Gold and no Full Art card; at most 30 packs are read. Any source counts.
  create or replace function public.cards_pity_count(p_user uuid)
    returns integer
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    r record;
    n integer := 0;
  begin
    for r in select p.cards from public.cards_packs p where p.user_id = p_user order by p.opened_at desc, p.id desc limit 30 loop
      exit when exists (select 1 from public.cards_catalog c where c.card_no = any (r.cards) and c.rarity in ('UR', 'L'));
      n := n + 1;
    end loop;
    return n;
  end
  $f$;

  -- The guarantee needs a Gold card to give: one in packs whose entity is active.
  create or replace function public.cards_pity_pool()
    returns boolean
    language sql stable security definer set search_path = public
    as $f$
      select exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id where c.rarity = 'UR' and c.in_packs and e.active)
    $f$;

  -- True when a focus pack was opened on the Paris day of p_now.
  create or replace function public.cards_focus_used(p_user uuid, p_now timestamptz default now())
    returns boolean
    language sql stable security definer set search_path = public
    as $f$
      select exists (select 1 from public.cards_packs p
       where p.user_id = p_user and p.focus is not null
         and p.opened_at >= ((p_now at time zone 'Europe/Paris')::date)::timestamp at time zone 'Europe/Paris'
         and p.opened_at < ((p_now at time zone 'Europe/Paris')::date + 1)::timestamp at time zone 'Europe/Paris')
    $f$;

  -- The wallet, read only. Same keys as 002, plus timer_used (refills since Paris midnight), timer_cap, timer_left, pity_left (packs left up
  -- to and including the one with the guaranteed Gold card, null while no Gold card is in packs) and focus_used. next_at is null once the
  -- day's timer refills are all used (the stack adds nothing until midnight).
  drop function if exists public.cards_wallet(uuid, timestamptz, integer, integer);
  create or replace function public.cards_wallet(
      p_user uuid, p_now timestamptz default now(), p_ads_limit integer default 10, p_bonus_cap integer default 3, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_stock integer;
    v_anchor timestamptz;
    v_bonus_seen integer;
    v_timer integer;
  begin
    select * into w from public.cards_wallets where user_id = p_user;
    if not found then
      w.stock := 5; w.anchor := p_now; w.paris_day := v_today; w.ads_today := 0; w.bonus_today := 0; w.shards := 0; w.timer_today := 0;
    end if;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap);
    v_stock := (r ->> 'stock')::integer;
    v_anchor := (r ->> 'anchor')::timestamptz;
    v_timer := (r ->> 'timer_today')::integer;
    v_bonus_seen := case when p_bonus_cap <= 0 then 0 else public.cards_bonus_plays(p_user, v_today) end;
    return jsonb_build_object(
      'stock', v_stock,
      'anchor', v_anchor,
      'paris_day', v_today,
      'ads_today', (r ->> 'ads_today')::integer,
      'bonus_today', (r ->> 'bonus_today')::integer,
      'shards', w.shards,
      'ads_left', greatest(0, p_ads_limit - (r ->> 'ads_today')::integer),
      'bonus_left', greatest(0, least(p_bonus_cap, v_bonus_seen) - (r ->> 'bonus_today')::integer),
      'next_at', case when v_stock >= 5 or v_timer >= p_timer_cap then null else v_anchor + interval '600 seconds' end,
      'midnight_at', ((v_today + 1)::timestamp at time zone 'Europe/Paris'),
      'timer_used', v_timer,
      'timer_cap', p_timer_cap,
      'timer_left', greatest(0, p_timer_cap - v_timer),
      'pity_left', case when public.cards_pity_pool() then greatest(1, 30 - public.cards_pity_count(p_user)) else null end,
      'focus_used', public.cards_focus_used(p_user, p_now));
  end
  $f$;

  -- The pack. As 002, plus: the timer fields of the wallet, the Gold guarantee (any source), the focus pack, the pair mark, the moment
  -- columns and the wishlist cleanup. An 'ad' pack is refused (the rewarded ad gives shards, cards_ad_grant). p_ticket is kept in the
  -- signature for the callers of 002 and ignored.
  drop function if exists public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer);
  create or replace function public.cards_apply_pack(
      p_user uuid, p_source text, p_cards integer[], p_ticket uuid default null, p_now timestamptz default now(),
      p_ads_limit integer default 10, p_bonus_cap integer default 3, p_timer_cap integer default 40, p_focus text default null)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_stock integer;
    v_anchor timestamptz;
    v_ads integer;
    v_bonus integer;
    v_timer integer;
    v_shards integer;
    v_ok integer;
    v_want integer;
    v_fifth text;
    v_card integer;
    v_new boolean;
    v_pair boolean;
    v_part smallint;
    v_c record;
    v_out jsonb := '[]'::jsonb;
    v_seen integer[] := '{}';
    v_pack uuid;
    v_packno integer;
    v_newn integer := 0;
    v_i integer;
    v_rarity text;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_source is null or p_source not in ('stock', 'shards', 'bonus') then raise exception 'cards: source'; end if;
    if p_cards is null or cardinality(p_cards) <> 5 or array_position(p_cards, null) is not null then raise exception 'cards: pack'; end if;

    select count(distinct c.card_no) into v_ok
      from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
     where c.card_no = any (p_cards) and c.in_packs and e.active;
    select count(distinct x) into v_want from unnest(p_cards) as x;
    if v_ok <> v_want then raise exception 'cards: pack'; end if;
    select rarity into v_fifth from public.cards_catalog where card_no = p_cards[5];
    if v_fifth = 'C' then raise exception 'cards: pack'; end if;

    if p_focus is not null and p_source <> 'stock' then raise exception 'cards: focus'; end if;

    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 5, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;

    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap);
    v_stock := (r ->> 'stock')::integer;
    v_anchor := (r ->> 'anchor')::timestamptz;
    v_ads := (r ->> 'ads_today')::integer;
    v_bonus := (r ->> 'bonus_today')::integer;
    v_timer := (r ->> 'timer_today')::integer;
    v_shards := w.shards;

    if p_source = 'stock' then
      -- A pack in the stack always opens, whatever the day's timer count (A13: the cap only stops the stack from refilling).
      if v_stock < 1 then raise exception 'cards: empty'; end if;
      v_stock := v_stock - 1;
    elsif p_source = 'shards' then
      if v_shards < 50 then raise exception 'cards: shards'; end if;
      v_shards := v_shards - 50;
    else
      if p_bonus_cap <= 0 or v_bonus >= least(p_bonus_cap, public.cards_bonus_plays(p_user, v_today)) then raise exception 'cards: bonus'; end if;
      v_bonus := v_bonus + 1;
    end if;

    -- A11 (PITY_UR 30 in rules.ts): after 29 packs in a row with no Gold and no Full Art, the 5th card of the 30th pack must be Gold, only
    -- while a Gold card is in packs. Any source counts. The refusal rolls the whole call back.
    if public.cards_pity_count(p_user) >= 29 and public.cards_pity_pool() and v_fifth is distinct from 'UR' then
      raise exception 'cards: pity';
    end if;

    -- A17: a focus pack is a pack of the stack, once a Paris day, for a group; cards 2 and 4 come from the group's cards (its own and those
    -- of its idols) unless the group has no card of their rarity.
    if p_focus is not null then
      if not exists (select 1 from public.cards_entities where id = p_focus and kind = 'group' and active) then raise exception 'cards: focus'; end if;
      if public.cards_focus_used(p_user, p_now) then raise exception 'cards: focus_used'; end if;
      foreach v_i in array array[2, 4] loop
        select c.rarity into v_rarity from public.cards_catalog c where c.card_no = p_cards[v_i];
        if not exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
                        where c.card_no = p_cards[v_i] and (c.entity_id = p_focus or e.group_id = p_focus))
           and exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
                        where c.rarity = v_rarity and c.in_packs and e.active and (c.entity_id = p_focus or e.group_id = p_focus)) then
          raise exception 'cards: pack';
        end if;
      end loop;
    end if;

    select count(*) + 1 into v_packno from public.cards_packs where user_id = p_user;

    foreach v_card in array p_cards loop
      v_new := not (v_card = any (v_seen)) and not exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_card);
      v_seen := v_seen || v_card;
      -- A12: a new card whose other half (same subject, same rarity, the other part) is already owned completes the pair. The cards of this
      -- pack stored before this one count, because they are in cards_owned by now.
      v_pair := false;
      if v_new then
        v_newn := v_newn + 1;
        select c.entity_id, c.rarity, c.part into v_c from public.cards_catalog c where c.card_no = v_card;
        v_part := v_c.part;
        if v_part in (1, 2) then
          v_pair := exists (select 1 from public.cards_catalog h join public.cards_owned o on o.card_no = h.card_no and o.user_id = p_user
                             where h.entity_id = v_c.entity_id and h.rarity = v_c.rarity and h.part = 3 - v_part);
        end if;
      end if;
      insert into public.cards_owned as o (user_id, card_no, copies, first_at, last_at, first_pack_no, first_source)
      values (p_user, v_card, 1, p_now, p_now, v_packno, 'pack')
      on conflict (user_id, card_no) do update set copies = o.copies + 1, last_at = p_now;
      v_out := v_out || jsonb_build_array(jsonb_build_object('n', v_card, 'isNew', v_new, 'completesPair', v_pair));
    end loop;
    delete from public.cards_wishlist where user_id = p_user and card_no = any (p_cards);

    insert into public.cards_packs (user_id, source, cards, opened_at, focus, new_count)
    values (p_user, p_source, p_cards, p_now, p_focus, v_newn) returning id into v_pack;

    update public.cards_wallets
       set stock = v_stock, anchor = v_anchor, paris_day = v_today, ads_today = v_ads, bonus_today = v_bonus, timer_today = v_timer,
           shards = v_shards, version = version + 1, updated_at = p_now
     where user_id = p_user;

    return jsonb_build_object('id', v_pack, 'source', p_source, 'cards', v_out, 'new_count', v_newn, 'pack_no', v_packno);
  end
  $f$;

  -- Lot 4 B4: the rewarded ad. A ticket issued before the ad (cards_issue_ticket) is spent once, between 10 seconds and 1 hour after it was
  -- issued (a ticket refused for its age is not spent, the call rolls back), the day's ads are counted (p_ads_limit, default 10) and
  -- p_shards shards are added. Google's rewarded event itself cannot be checked on the server: the route calls this only after it.
  create or replace function public.cards_ad_grant(
      p_user uuid, p_ticket uuid, p_now timestamptz default now(), p_ads_limit integer default 10, p_shards integer default 25, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_ads integer;
    v_t uuid;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_shards is null or p_shards < 1 or p_shards > 1000 then raise exception 'cards: source'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 5, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap);
    v_ads := (r ->> 'ads_today')::integer;
    if v_ads >= p_ads_limit then raise exception 'cards: ad_limit'; end if;
    update public.cards_ad_tickets set used_at = p_now
     where id = p_ticket and user_id = p_user and used_at is null
       and issued_at <= p_now - interval '10 seconds' and issued_at >= p_now - interval '1 hour'
    returning id into v_t;
    if v_t is null then raise exception 'cards: ticket'; end if;
    update public.cards_wallets
       set stock = (r ->> 'stock')::integer, anchor = (r ->> 'anchor')::timestamptz, paris_day = v_today, ads_today = v_ads + 1,
           bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           shards = shards + p_shards, version = version + 1, updated_at = p_now
     where user_id = p_user;
    return jsonb_build_object('gained', p_shards, 'shards', w.shards + p_shards, 'ads_today', v_ads + 1);
  end
  $f$;

  -- Lot 3 A14: craft a missing card with shards. The card must be in packs with an active entity, the player must not own it, and a Full Art
  -- cannot be crafted. The cost is the rarity's (CRAFT_COST in rules.ts: C 10, U 20, R 50, SR 120, UR 300). Wallet locked like cards_apply_pack.
  create or replace function public.cards_craft(p_user uuid, p_card_no integer, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_rarity text;
    v_cost integer;
    v_packno integer;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    select c.rarity into v_rarity
      from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
     where c.card_no = p_card_no and c.in_packs and e.active;
    if v_rarity is null then raise exception 'cards: card'; end if;
    if v_rarity = 'L' then raise exception 'cards: no_craft'; end if;
    v_cost := case v_rarity when 'C' then 10 when 'U' then 20 when 'R' then 50 when 'SR' then 120 else 300 end;

    select * into w from public.cards_wallets where user_id = p_user for update;
    if not found then raise exception 'cards: shards'; end if;
    if exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = p_card_no) then raise exception 'cards: owned'; end if;
    if w.shards < v_cost then raise exception 'cards: shards'; end if;

    select count(*) into v_packno from public.cards_packs where user_id = p_user;
    update public.cards_wallets set shards = shards - v_cost, version = version + 1, updated_at = p_now where user_id = p_user;
    insert into public.cards_owned (user_id, card_no, copies, first_at, last_at, first_pack_no, first_source)
    values (p_user, p_card_no, 1, p_now, p_now, v_packno, 'craft');
    insert into public.cards_crafts (user_id, card_no, rarity, cost, crafted_at) values (p_user, p_card_no, v_rarity, v_cost, p_now);
    delete from public.cards_wishlist where user_id = p_user and card_no = p_card_no;
    return jsonb_build_object('card_no', p_card_no, 'rarity', v_rarity, 'cost', v_cost, 'shards', w.shards - v_cost);
  end
  $f$;

  -- Lot 3 A17: add a missing card to the wishlist or remove one. At most 50 cards; an owned card cannot be added; removing is always allowed.
  create or replace function public.cards_wish(p_user uuid, p_card_no integer, p_on boolean, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_n integer;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    -- The wallet row is the lock that serialises a player's writes (the 50 limit cannot be passed by two requests at once).
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 5, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    if coalesce(p_on, false) then
      if not exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id where c.card_no = p_card_no and c.in_packs and e.active) then
        raise exception 'cards: card';
      end if;
      if exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = p_card_no) then raise exception 'cards: owned'; end if;
      if not exists (select 1 from public.cards_wishlist x where x.user_id = p_user and x.card_no = p_card_no) then
        select count(*) into v_n from public.cards_wishlist x where x.user_id = p_user;
        if v_n >= 50 then raise exception 'cards: wish_limit'; end if;
        insert into public.cards_wishlist (user_id, card_no, added_at) values (p_user, p_card_no, p_now);
      end if;
    else
      delete from public.cards_wishlist where user_id = p_user and card_no = p_card_no;
    end if;
    select count(*) into v_n from public.cards_wishlist x where x.user_id = p_user;
    return jsonb_build_object('on', exists (select 1 from public.cards_wishlist x where x.user_id = p_user and x.card_no = p_card_no), 'count', v_n);
  end
  $f$;

  -- Lot 4 B3: the last packs of a player, newest first: when, the best rarity of the five cards, the source and the new cards. The rows that
  -- came before 104 have no new_count (null).
  create or replace function public.cards_recent_packs(p_user uuid, p_limit integer default 10)
    returns jsonb
    language sql stable security definer set search_path = public
    as $f$
      select coalesce(jsonb_agg(jsonb_build_object('opened_at', x.opened_at, 'best', x.best, 'source', x.source, 'new_count', x.new_count)
                                order by x.opened_at desc, x.id desc), '[]'::jsonb)
        from (
          select p.id, p.opened_at, p.source, p.new_count,
                 (select c.rarity from public.cards_catalog c where c.card_no = any (p.cards)
                   order by array_position(array['C', 'U', 'R', 'SR', 'UR', 'L'], c.rarity) desc limit 1) as best
            from public.cards_packs p where p.user_id = p_user order by p.opened_at desc, p.id desc limit greatest(1, least(coalesce(p_limit, 10), 50))
        ) x
    $f$;

  revoke all on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_pity_count(uuid) from public, anon, authenticated;
  revoke all on function public.cards_pity_pool() from public, anon, authenticated;
  revoke all on function public.cards_focus_used(uuid, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_wallet(uuid, timestamptz, integer, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer, integer, text) from public, anon, authenticated;
  revoke all on function public.cards_ad_grant(uuid, uuid, timestamptz, integer, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_craft(uuid, integer, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_wish(uuid, integer, boolean, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_recent_packs(uuid, integer) from public, anon, authenticated;
  grant execute on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer) to service_role;
  grant execute on function public.cards_pity_count(uuid) to service_role;
  grant execute on function public.cards_pity_pool() to service_role;
  grant execute on function public.cards_focus_used(uuid, timestamptz) to service_role;
  grant execute on function public.cards_wallet(uuid, timestamptz, integer, integer, integer) to service_role;
  grant execute on function public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer, integer, text) to service_role;
  grant execute on function public.cards_ad_grant(uuid, uuid, timestamptz, integer, integer, integer) to service_role;
  grant execute on function public.cards_craft(uuid, integer, timestamptz) to service_role;
  grant execute on function public.cards_wish(uuid, integer, boolean, timestamptz) to service_role;
  grant execute on function public.cards_recent_packs(uuid, integer) to service_role;

  if (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_wallet') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_apply_pack') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_roll') <> 1 then
    raise exception '104-economy: cards_roll, cards_wallet and cards_apply_pack must each exist once';
  end if;
  if exists (select 1 from pg_tables where schemaname = 'public' and tablename in ('cards_crafts', 'cards_wishlist') and not rowsecurity) then
    raise exception '104-economy: a new table has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_crafts', 'cards_wishlist')
             and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '104-economy: a new table is granted to a browser role';
  end if;

  notify pgrst, 'reload schema';
end $c104$;

-- ==== 6/15: 105-goals.sql (verbatim) ====
-- 105-goals.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; the sets, the week, the claims and the shared ledgers)
--
-- What:   adds the database side of Missions, in ONE DO block:
--           tables   cards_sets_claimed   one row per player and set: the set is claimed, its packs were given (never twice)
--                    cards_week_claims    one row per player and Paris week: the week's reward was claimed
--                    cards_idem           the idempotency ledger: one row per player and key, with the stored answer (a retry or a double tap
--                                         returns it and never spends or gives twice); shared by 105 and 110 to 112; kept 24 hours by cards_idem_gc
--                    cards_audit          the audit trail of every spending write (openings, claims, crafts, recycles, ad grants, friends)
--           constraint cards_wallets_stock_check   now stock >= 0 and <= 500 (a claimed set pays straight into the stack, which may pass its cap)
--           new functions
--                    cards_goals_progress(user, cards)   every set with its card count, the cards the player owns and whether it is claimed
--                    cards_week_progress(user, now)      the week's three counters, the Paris week and whether it is claimed
--                    cards_missions(user, now)           the week and every set (what Missions shows)
--                    cards_claim(user, key, target, now, timer_cap)   claims one set or the week once, adds its packs to the STACK and its shards
--                    cards_idem_gc(now)                  deletes the idempotency rows older than 24 hours
-- Why:    the prototype v6 (Missions): a set with a fixed reward, claimed by the player's tap, pays its packs into the stack; the weekly list of
--         three goals pays +2 packs and +25 shards; no streak and nothing lost by a missed week. Every number comes from the player's own rows
--         (packs, Kpopdle wins decided in the database, first copies): nothing is typed in by a browser. A claim is idempotent by its key.
-- Sets:   a set is complete when the player owns every card of it that is in packs today (cards_catalog.in_packs and an active entity). A claimed
--         set never pays twice, even if the catalog grows later. The sets and their packs:
--           group:<id>   a group (a group entity with a card in packs): its own cards and the cards of its idols (cards_entities.group_id)   +1
--           solo         the soloists: every idol card whose entity has no group subject (no group_id, or a group with no card in packs)   +1
--           holo         every Holo card (rarity R)                                                                                          +3
--           gold         every Gold card (rarity UR)                                                                                         +5
--           year:<yyyy>  a debut year (cards_entities.debut_year of the group entity) with 2 or more group subjects: all their set cards   +2
-- Week:   Monday 00:00 to the next Monday 00:00, Europe/Paris. 20 packs opened (cards_packs.opened_at, any source), 3 Kpopdle wins (dle_plays won,
--         finished in the week; 0 on a database without 019) and 10 cards new to the player (cards_owned.first_at in the week, a craft included).
--         All three done and claimed once: +2 packs and +25 shards. A missed week takes nothing away.
-- Rows:   0 rows. 4 tables, 1 constraint, 5 new functions. Additive. No XP, level, streak or badge of kpopquiz.org is read or written.
-- Needs:  001, 002 and 104 (cards_roll with 8 arguments). 019 is optional (Kpopdle wins).
-- Errors: words after "cards: ": claimed (already claimed), goal (the set or the week is not complete), set (no such set), idem_conflict (the key was
--         used for another operation), user.
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_goals_progress', 'cards_week_progress', 'cards_missions', 'cards_claim', 'cards_idem_gc');   expect 5
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_%';   expect f
-- Verify: select count(*) from pg_tables where schemaname = 'public' and tablename in ('cards_sets_claimed', 'cards_week_claims', 'cards_idem', 'cards_audit') and rowsecurity;   expect 4
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_sets_claimed', 'cards_week_claims', 'cards_idem', 'cards_audit') and grantee in ('anon', 'authenticated');   expect 0
-- Verify: select pg_get_constraintdef(oid) like '%500%' from pg_constraint where conname = 'cards_wallets_stock_check' and conrelid = 'public.cards_wallets'::regclass;   expect t
-- Verify: select (public.cards_week_progress('00000000-0000-0000-0000-000000000000', '2026-11-12 10:00+00')) ->> 'week_start';   expect 2026-11-09
-- Verify: select count(*) from public.cards_sets_claimed;   expect 0 right after the first run (nothing is claimed for you)
-- Undo:   105-goals.rollback.sql (refused while a claim or an idempotency row is recorded, or a stack is above 5)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c105$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_wallets') is null or to_regclass('public.cards_catalog') is null or to_regclass('public.cards_packs') is null
     or to_regclass('public.cards_owned') is null or to_regclass('public.cards_entities') is null then
    raise exception '105-goals: run 001-schema.sql first';
  end if;
  if to_regprocedure('public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer)') is null then
    raise exception '105-goals: run 104-economy.sql first';
  end if;

  if exists (select 1 from pg_constraint where conname = 'cards_wallets_stock_check' and conrelid = 'public.cards_wallets'::regclass
              and pg_get_constraintdef(oid) not like '%500%') then
    alter table public.cards_wallets drop constraint cards_wallets_stock_check;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cards_wallets_stock_check' and conrelid = 'public.cards_wallets'::regclass) then
    alter table public.cards_wallets add constraint cards_wallets_stock_check check (stock between 0 and 500);
  end if;

  -- The sets a player has claimed. No foreign key on the set: a catalog rebuild must not erase what was paid.
  create table if not exists public.cards_sets_claimed (
    user_id uuid not null constraint cards_sets_claimed_user_id_fkey references auth.users(id) on delete cascade,
    set_id text not null constraint cards_sets_claimed_set_id_check check (set_id ~ '^(group:.+|solo|holo|gold|year:[0-9]{4})$'),
    kind text not null constraint cards_sets_claimed_kind_check check (kind in ('group', 'solo', 'holo', 'gold', 'year')),
    packs integer not null constraint cards_sets_claimed_packs_check check (packs > 0),
    claimed_at timestamptz not null default now(),
    constraint cards_sets_claimed_pkey primary key (user_id, set_id)
  );
  alter table public.cards_sets_claimed enable row level security;
  revoke all on table public.cards_sets_claimed from public, anon, authenticated;
  grant all on table public.cards_sets_claimed to service_role;

  create table if not exists public.cards_week_claims (
    user_id uuid not null constraint cards_week_claims_user_id_fkey references auth.users(id) on delete cascade,
    week_start date not null,
    packs integer not null constraint cards_week_claims_packs_check check (packs > 0),
    shards integer not null constraint cards_week_claims_shards_check check (shards > 0),
    claimed_at timestamptz not null default now(),
    constraint cards_week_claims_pkey primary key (user_id, week_start)
  );
  alter table public.cards_week_claims enable row level security;
  revoke all on table public.cards_week_claims from public, anon, authenticated;
  grant all on table public.cards_week_claims to service_role;

  -- The idempotency ledger. op names the operation and its parameters ('open:stock:5'), response is what the caller got.
  create table if not exists public.cards_idem (
    user_id uuid not null constraint cards_idem_user_id_fkey references auth.users(id) on delete cascade,
    idem_key text not null constraint cards_idem_key_check check (length(idem_key) between 8 and 64),
    op text not null,
    response jsonb not null,
    created_at timestamptz not null default now(),
    constraint cards_idem_pkey primary key (user_id, idem_key)
  );
  alter table public.cards_idem enable row level security;
  revoke all on table public.cards_idem from public, anon, authenticated;
  grant all on table public.cards_idem to service_role;
  create index if not exists cards_idem_created_idx on public.cards_idem (created_at);

  -- The audit trail: one row per spending write. No foreign key on the player (the trail outlives an account for dispute handling).
  create table if not exists public.cards_audit (
    id bigint generated always as identity constraint cards_audit_pkey primary key,
    user_id uuid not null,
    kind text not null constraint cards_audit_kind_check check (kind in ('open', 'claim', 'craft', 'recycle', 'ad', 'friend', 'demo')),
    idem_key text,
    detail jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now()
  );
  alter table public.cards_audit enable row level security;
  revoke all on table public.cards_audit from public, anon, authenticated;
  grant all on table public.cards_audit to service_role;
  create index if not exists cards_audit_user_idx on public.cards_audit (user_id, created_at desc);
  create index if not exists cards_audit_kind_idx on public.cards_audit (kind, created_at desc);

  -- Every set with its cards in packs today, how many of them the player owns, and whether the set is claimed. p_cards limits the answer to
  -- the sets that hold one of those cards (the sets a pack or a craft can have completed); each set still counts ALL its cards.
  create or replace function public.cards_goals_progress(p_user uuid, p_cards integer[] default null)
    returns table (set_id text, kind text, name text, packs integer, total integer, owned integer, claimed boolean)
    language sql stable security definer set search_path = public
    as $f$
      with live as (
        select c.card_no, c.rarity, c.entity_id, e.kind as ekind, e.group_id, e.name as ename
          from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
         where c.in_packs and e.active),
      subj as (select distinct l.entity_id as gid from live l where l.ekind = 'group'),
      gm as (
        select l.entity_id as sid, l.ename as sname, l.card_no from live l where l.ekind = 'group'
        union all
        select l.group_id, g.name, l.card_no
          from live l join public.cards_entities g on g.id = l.group_id
         where l.ekind = 'idol' and l.group_id in (select gid from subj)),
      yrs as (
        select g.debut_year as y from public.cards_entities g where g.id in (select gid from subj) and g.debut_year is not null
         group by g.debut_year having count(*) >= 2),
      m as (
        select gm.sid, 'group'::text as skind, gm.sname, 1 as spacks, gm.card_no from gm
        union all
        select 'solo', 'solo', null, 1, l.card_no from live l
         where l.ekind = 'idol' and (l.group_id is null or l.group_id not in (select gid from subj))
        union all select 'holo', 'holo', null, 3, l.card_no from live l where l.rarity = 'R'
        union all select 'gold', 'gold', null, 5, l.card_no from live l where l.rarity = 'UR'
        union all
        select 'year:' || g.debut_year::text, 'year', g.debut_year::text, 2, gm.card_no
          from gm join public.cards_entities g on g.id = gm.sid where g.debut_year in (select y from yrs)),
      sel as (select distinct m.sid from m where p_cards is null or m.card_no = any (p_cards))
      select m.sid, m.skind, min(m.sname), min(m.spacks)::integer, count(*)::integer, count(o.card_no)::integer, (cl.user_id is not null)
        from m join sel on sel.sid = m.sid
        left join public.cards_owned o on o.user_id = p_user and o.card_no = m.card_no
        left join public.cards_sets_claimed cl on cl.user_id = p_user and cl.set_id = m.sid
       group by m.sid, m.skind, cl.user_id
    $f$;

  -- The week of p_now: Monday 00:00 to the next Monday 00:00, Europe/Paris. Read only.
  create or replace function public.cards_week_progress(p_user uuid, p_now timestamptz default now())
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_start date := (date_trunc('week', v_today::timestamp))::date;
    v_from timestamptz := v_start::timestamp at time zone 'Europe/Paris';
    v_to timestamptz := (v_start + 7)::timestamp at time zone 'Europe/Paris';
    v_packs integer;
    v_wins integer := 0;
    v_new integer;
    v_claimed boolean;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    select count(*) into v_packs from public.cards_packs p where p.user_id = p_user and p.opened_at >= v_from and p.opened_at < v_to;
    select count(*) into v_new from public.cards_owned o where o.user_id = p_user and o.first_at >= v_from and o.first_at < v_to;
    -- The Kpopdle wins, read the way cards_bonus_record reads them: a win is decided in the database (dle_guess), never reported by a browser.
    -- A play's date is its UTC day or the day before (dle_playable), so the Monday's plays start two dates earlier. A database without the
    -- daily games (019 not applied) counts none.
    if to_regclass('public.dle_plays') is not null and to_regclass('public.dle_games') is not null then
      select count(*) into v_wins
        from public.dle_plays d
       where d.game_id = any (array(select g.id from public.dle_games g where g.id like 'kpopdle%'))
         and d.play_date between v_start - 2 and v_today
         and d.user_id = p_user and d.status = 'won'
         and d.finished_at >= v_from and d.finished_at < v_to and d.finished_at <= p_now;
    end if;
    v_claimed := exists (select 1 from public.cards_week_claims k where k.user_id = p_user and k.week_start = v_start);
    return jsonb_build_object(
      'week_start', v_start, 'starts_at', v_from, 'ends_at', v_to,
      'packs_opened', v_packs, 'kpopdle_wins', v_wins, 'new_cards', v_new,
      'goal_packs', 20, 'goal_wins', 3, 'goal_cards', 10,
      'reward_packs', 2, 'reward_shards', 25,
      'done', v_packs >= 20 and v_wins >= 3 and v_new >= 10,
      'claimed', v_claimed);
  end
  $f$;

  -- What Missions shows: the week and every set (ready ones are complete and not claimed).
  create or replace function public.cards_missions(p_user uuid, p_now timestamptz default now())
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    v_sets jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('id', x.set_id, 'kind', x.kind, 'name', x.name, 'packs', x.packs, 'total', x.total, 'owned', x.owned, 'claimed', x.claimed)
                              order by array_position(array['gold', 'holo', 'year', 'solo', 'group'], x.kind), x.name, x.set_id), '[]'::jsonb)
      into v_sets from public.cards_goals_progress(p_user, null) x;
    return jsonb_build_object('week', public.cards_week_progress(p_user, p_now), 'sets', v_sets);
  end
  $f$;

  -- Claims one set (p_target = the set id) or the week (p_target = 'week'), once. The packs go straight into the stack (which may then pass its
  -- cap: the cap only stops the timer), the week's shards into the shards. The wallet row is locked first, so two taps cannot both pay; the
  -- same p_key returns the stored answer ("replayed"). Words: claimed, goal, set, idem_conflict.
  create or replace function public.cards_claim(
      p_user uuid, p_key text, p_target text, p_now timestamptz default now(), p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_op text := 'claim:' || coalesce(p_target, '');
    v_hit public.cards_idem%rowtype;
    v_wk jsonb;
    v_set record;
    v_packs integer := 0;
    v_shards integer := 0;
    v_out jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    if p_target is null or length(p_target) > 80 then raise exception 'cards: set'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;

    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> v_op then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;

    if p_target = 'week' then
      v_wk := public.cards_week_progress(p_user, p_now);
      if (v_wk ->> 'claimed')::boolean then raise exception 'cards: claimed'; end if;
      if not (v_wk ->> 'done')::boolean then raise exception 'cards: goal'; end if;
      insert into public.cards_week_claims (user_id, week_start, packs, shards, claimed_at)
      values (p_user, (v_wk ->> 'week_start')::date, (v_wk ->> 'reward_packs')::integer, (v_wk ->> 'reward_shards')::integer, p_now);
      v_packs := (v_wk ->> 'reward_packs')::integer;
      v_shards := (v_wk ->> 'reward_shards')::integer;
    else
      select x.* into v_set from public.cards_goals_progress(p_user, null) x where x.set_id = p_target;
      if not found then raise exception 'cards: set'; end if;
      if v_set.claimed then raise exception 'cards: claimed'; end if;
      if v_set.total < 1 or v_set.owned < v_set.total then raise exception 'cards: goal'; end if;
      insert into public.cards_sets_claimed (user_id, set_id, kind, packs, claimed_at) values (p_user, v_set.set_id, v_set.kind, v_set.packs, p_now);
      v_packs := v_set.packs;
    end if;

    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap);
    update public.cards_wallets
       set stock = (r ->> 'stock')::integer + v_packs, anchor = (r ->> 'anchor')::timestamptz, paris_day = v_today,
           ads_today = (r ->> 'ads_today')::integer, bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           shards = shards + v_shards, version = version + 1, updated_at = p_now
     where user_id = p_user;
    v_out := jsonb_build_object('replayed', false, 'target', p_target, 'packs', v_packs, 'shards', v_shards);
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, v_op, v_out, p_now);
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at) values (p_user, 'claim', p_key, v_out, p_now);
    return v_out;
  end
  $f$;

  create or replace function public.cards_idem_gc(p_now timestamptz default now())
    returns integer
    language plpgsql security definer set search_path = public
    as $f$
  declare
    n integer;
  begin
    delete from public.cards_idem where created_at < p_now - interval '24 hours';
    get diagnostics n = row_count;
    return n;
  end
  $f$;

  revoke all on function public.cards_goals_progress(uuid, integer[]) from public, anon, authenticated;
  revoke all on function public.cards_week_progress(uuid, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_missions(uuid, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_claim(uuid, text, text, timestamptz, integer) from public, anon, authenticated;
  revoke all on function public.cards_idem_gc(timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_goals_progress(uuid, integer[]) to service_role;
  grant execute on function public.cards_week_progress(uuid, timestamptz) to service_role;
  grant execute on function public.cards_missions(uuid, timestamptz) to service_role;
  grant execute on function public.cards_claim(uuid, text, text, timestamptz, integer) to service_role;
  grant execute on function public.cards_idem_gc(timestamptz) to service_role;

  if exists (select 1 from pg_tables where schemaname = 'public' and tablename in ('cards_sets_claimed', 'cards_week_claims', 'cards_idem', 'cards_audit') and not rowsecurity) then
    raise exception '105-goals: a new table has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_sets_claimed', 'cards_week_claims', 'cards_idem', 'cards_audit')
             and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '105-goals: a new table is granted to a browser role';
  end if;

  notify pgrst, 'reload schema';
end $c105$;

-- ==== 7/15: 106-demo.sql (verbatim) ====
-- 106-demo.sql (Bunnyverse Cards lot 3, 2026-11-13; lane UI, integrator point A18 / lot 4 C5: the guest demo pack)
--
-- What:   adds the claim of a demo pack. A signed-out visitor opens ONE demo pack (drawn by the server, signed with an HMAC the server
--         keeps); when the visitor signs in, the browser posts that token once and the five cards are added to the binder. This file
--         holds the table of claims and the one function that adds the cards:
--           cards_demo_claims                      one row per claimed token
--           cards_demo_claim(user, jti, cards, device_hash, ip_hash, now)   checks the limits, stores the claim, adds the cards
--         The token itself (its signature and its age) is checked by the server route before this function runs; this function never sees
--         a secret. The device id and the IP address arrive HASHED with a salt only the server knows; the database never holds either one in
--         the clear.
-- Rules:  one claim per token (jti is the key); at most 1 claim a day per device hash and 3 a day per IP hash (the Paris day of p_now);
--         rows older than 7 days are deleted by the function on each call, so a token must not live longer than that (the route gives it
--         2 days). A Team account never claims: the route refuses it before calling (teamRefusal); the function adds nothing for a
--         card that is no longer in packs. If cards_owned has the column first_source (lane ECON), a card that is new to the player is
--         marked 'demo' there; without that column, or if its check refuses the word, nothing more is written.
-- Why:    the owner wants a visitor to feel a pack before creating an account, and the cards to be real afterwards: the demo is attached to
--         the account, not thrown away. No wallet, stock, shard or pack row is touched: a demo costs nothing and is not a pack of the stack.
-- Rows:   0 rows. 1 table, 3 indexes besides the key, 1 function. Additive: no existing table or function is changed.
-- Needs:  001 and 002 (cards_catalog, cards_entities, cards_owned); auth.users.
-- Errors: a refusal is an exception whose message starts with 'cards: ' and one word: user, pack, demo_used (the token was claimed),
--         demo_device (this device claimed one today), demo_ip (3 claims today from this network).
-- Verify: select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'cards_demo_claims';   expect 1
-- Verify: select relrowsecurity from pg_class where oid = 'public.cards_demo_claims'::regclass;   expect t
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_demo_claims' and grantee in ('anon', 'authenticated', 'PUBLIC');   expect 0
-- Verify: select has_function_privilege('service_role', 'public.cards_demo_claim(uuid, text, integer[], text, text, timestamptz)', 'execute');   expect t
-- Verify: select has_function_privilege('anon', 'public.cards_demo_claim(uuid, text, integer[], text, text, timestamptz)', 'execute') or has_function_privilege('authenticated', 'public.cards_demo_claim(uuid, text, integer[], text, text, timestamptz)', 'execute');   expect f
-- Verify: select count(*) from public.cards_demo_claims;   expect 0
-- Undo:   106-demo.rollback.sql (drops the function and the table; the cards already added to binders stay).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c106$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_owned') is null or to_regclass('public.cards_catalog') is null or to_regclass('public.cards_entities') is null then
    raise exception '106-demo: run 001-schema.sql and 002-functions.sql first';
  end if;

  create table if not exists public.cards_demo_claims (
    jti text constraint cards_demo_claims_pkey primary key constraint cards_demo_claims_jti_check check (length(jti) between 16 and 64),
    user_id uuid not null constraint cards_demo_claims_user_id_fkey references auth.users(id) on delete cascade,
    device_hash text not null constraint cards_demo_claims_device_check check (length(device_hash) between 16 and 128),
    ip_hash text not null constraint cards_demo_claims_ip_check check (length(ip_hash) between 16 and 128),
    cards integer[] not null constraint cards_demo_claims_cards_check check (cardinality(cards) = 5),
    claimed_day date not null,
    claimed_at timestamptz not null default now()
  );
  alter table public.cards_demo_claims enable row level security;
  revoke all on table public.cards_demo_claims from public, anon, authenticated;
  create index if not exists cards_demo_claims_device_idx on public.cards_demo_claims (device_hash, claimed_day);
  create index if not exists cards_demo_claims_ip_idx on public.cards_demo_claims (ip_hash, claimed_day);
  create index if not exists cards_demo_claims_at_idx on public.cards_demo_claims (claimed_at);

  create or replace function public.cards_demo_claim(
      p_user uuid, p_jti text, p_cards integer[], p_device text, p_ip text, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_day date := (p_now at time zone 'Europe/Paris')::date;
    v_card integer;
    v_new boolean;
    v_seen integer[] := '{}';
    v_out jsonb := '[]'::jsonb;
    v_ok integer;
    v_has_src boolean;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_jti is null or length(p_jti) not between 16 and 64 then raise exception 'cards: demo_used'; end if;
    if p_cards is null or cardinality(p_cards) <> 5 or array_position(p_cards, null) is not null then raise exception 'cards: pack'; end if;
    if p_device is null or p_ip is null then raise exception 'cards: user'; end if;

    -- Serialise the claims of one device and one network, so two tabs cannot both pass the count.
    perform pg_advisory_xact_lock(hashtext('cards_demo:d:' || p_device));
    perform pg_advisory_xact_lock(hashtext('cards_demo:i:' || p_ip));

    -- The rows older than 7 days go (the IP hash is kept no longer than that).
    delete from public.cards_demo_claims where claimed_at < p_now - interval '7 days';

    if exists (select 1 from public.cards_demo_claims where jti = p_jti) then raise exception 'cards: demo_used'; end if;
    if (select count(*) from public.cards_demo_claims where device_hash = p_device and claimed_day = v_day) >= 1 then raise exception 'cards: demo_device'; end if;
    if (select count(*) from public.cards_demo_claims where ip_hash = p_ip and claimed_day = v_day) >= 3 then raise exception 'cards: demo_ip'; end if;

    -- Only the cards still in packs are added (a photo may have been retired since the token was signed). None left: nothing to claim.
    select count(distinct c.card_no) into v_ok
      from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
     where c.card_no = any (p_cards) and c.in_packs and e.active;
    if v_ok = 0 then raise exception 'cards: pack'; end if;

    insert into public.cards_demo_claims (jti, user_id, device_hash, ip_hash, cards, claimed_day, claimed_at)
    values (p_jti, p_user, p_device, p_ip, p_cards, v_day, p_now);

    v_has_src := exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_owned' and column_name = 'first_source');

    foreach v_card in array p_cards loop
      if not exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
                      where c.card_no = v_card and c.in_packs and e.active) then
        continue;
      end if;
      v_new := not (v_card = any (v_seen)) and not exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_card);
      v_seen := v_seen || v_card;
      insert into public.cards_owned as o (user_id, card_no, copies, first_at, last_at)
      values (p_user, v_card, 1, p_now, p_now)
      on conflict (user_id, card_no) do update set copies = o.copies + 1, last_at = p_now;
      if v_new and v_has_src then
        -- Lane ECON's column: the first source of a card. If its check does not know 'demo', the card keeps what the column holds.
        begin
          execute 'update public.cards_owned set first_source = ''demo'' where user_id = $1 and card_no = $2' using p_user, v_card;
        exception when check_violation then
          null;
        end;
      end if;
      v_out := v_out || jsonb_build_array(jsonb_build_object('n', v_card, 'isNew', v_new));
    end loop;

    return jsonb_build_object('cards', v_out);
  end
  $f$;

  revoke all on function public.cards_demo_claim(uuid, text, integer[], text, text, timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_demo_claim(uuid, text, integer[], text, text, timestamptz) to service_role;
  -- The service role needs the table too (the function is security definer, but the purge and the tests read it).
  grant select, insert, delete on table public.cards_demo_claims to service_role;

  if not (select relrowsecurity from pg_class where oid = 'public.cards_demo_claims'::regclass) then
    raise exception '106-demo: cards_demo_claims has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_demo_claims'
             and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '106-demo: cards_demo_claims is granted to a browser role';
  end if;
end $c106$;

-- ==== 8/15: 107-prefs.sql (verbatim) ====
-- 107-prefs.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; the player's preferences: sound, vibration, pack theme, focus group)
--
-- What:   adds, in ONE DO block:
--           table     cards_prefs        one row per player: sound, vibration, the theme of the pack in the centre, the group of the focus pack
--           functions cards_prefs_get(user)            the preferences as jsonb (the defaults when the player has no row)
--                     cards_prefs_set(user, patch, now) merges a jsonb patch {sound, vibration, theme, focus} into the row, validated
-- Why:    the prototype v6 keeps sound and vibration as two separate switches and remembers the chosen theme and the focus group; the server
--         keeps them so a second device shows the same lobby, and so the server (not the browser) knows the theme a plain "Open a pack" uses.
-- Rows:   0 rows. 1 table, 2 functions. Additive. A player without a row reads the defaults (sound on, vibration on, theme all, no focus).
-- Needs:  001 (cards_entities).
-- Errors: "cards: pref" (an unknown theme, a value of the wrong type, or a focus that is not a group entity), "cards: user".
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_prefs_get', 'cards_prefs_set');   expect 2
-- Verify: select count(*) from pg_tables where schemaname = 'public' and tablename = 'cards_prefs' and rowsecurity;   expect 1
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_prefs' and grantee in ('anon', 'authenticated');   expect 0
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_prefs%';   expect f
-- Verify: select (public.cards_prefs_get('00000000-0000-0000-0000-000000000000')) ->> 'theme';   expect all
-- Undo:   107-prefs.rollback.sql (drops the table with its rows)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c107$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_entities') is null then
    raise exception '107-prefs: run 001-schema.sql first';
  end if;

  create table if not exists public.cards_prefs (
    user_id uuid constraint cards_prefs_pkey primary key constraint cards_prefs_user_id_fkey references auth.users(id) on delete cascade,
    sound boolean not null default true,
    vibration boolean not null default true,
    theme text not null default 'all' constraint cards_prefs_theme_check check (theme in ('all', 'girls', 'boys', 'solo')),
    focus text constraint cards_prefs_focus_fkey references public.cards_entities(id) on delete set null,
    updated_at timestamptz not null default now()
  );
  alter table public.cards_prefs enable row level security;
  revoke all on table public.cards_prefs from public, anon, authenticated;
  grant all on table public.cards_prefs to service_role;

  create or replace function public.cards_prefs_get(p_user uuid)
    returns jsonb
    language sql stable security definer set search_path = public
    as $f$
      select jsonb_build_object(
        'sound', coalesce((select x.sound from public.cards_prefs x where x.user_id = p_user), true),
        'vibration', coalesce((select x.vibration from public.cards_prefs x where x.user_id = p_user), true),
        'theme', coalesce((select x.theme from public.cards_prefs x where x.user_id = p_user), 'all'),
        'focus', (select x.focus from public.cards_prefs x where x.user_id = p_user))
    $f$;

  create or replace function public.cards_prefs_set(p_user uuid, p_patch jsonb, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    cur jsonb;
    v_sound boolean;
    v_vib boolean;
    v_theme text;
    v_focus text;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'cards: pref'; end if;
    cur := public.cards_prefs_get(p_user);
    v_sound := (cur ->> 'sound')::boolean;
    v_vib := (cur ->> 'vibration')::boolean;
    v_theme := cur ->> 'theme';
    v_focus := cur ->> 'focus';
    if p_patch ? 'sound' then
      if jsonb_typeof(p_patch -> 'sound') <> 'boolean' then raise exception 'cards: pref'; end if;
      v_sound := (p_patch ->> 'sound')::boolean;
    end if;
    if p_patch ? 'vibration' then
      if jsonb_typeof(p_patch -> 'vibration') <> 'boolean' then raise exception 'cards: pref'; end if;
      v_vib := (p_patch ->> 'vibration')::boolean;
    end if;
    if p_patch ? 'theme' then
      if jsonb_typeof(p_patch -> 'theme') <> 'string' or (p_patch ->> 'theme') not in ('all', 'girls', 'boys', 'solo') then raise exception 'cards: pref'; end if;
      v_theme := p_patch ->> 'theme';
    end if;
    if p_patch ? 'focus' then
      if jsonb_typeof(p_patch -> 'focus') = 'null' then v_focus := null;
      elsif jsonb_typeof(p_patch -> 'focus') = 'string'
            and exists (select 1 from public.cards_entities e where e.id = p_patch ->> 'focus' and e.kind = 'group' and e.active) then
        v_focus := p_patch ->> 'focus';
      else raise exception 'cards: pref';
      end if;
    end if;
    insert into public.cards_prefs (user_id, sound, vibration, theme, focus, updated_at) values (p_user, v_sound, v_vib, v_theme, v_focus, p_now)
    on conflict (user_id) do update set sound = excluded.sound, vibration = excluded.vibration, theme = excluded.theme, focus = excluded.focus, updated_at = excluded.updated_at;
    return public.cards_prefs_get(p_user);
  end
  $f$;

  revoke all on function public.cards_prefs_get(uuid) from public, anon, authenticated;
  revoke all on function public.cards_prefs_set(uuid, jsonb, timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_prefs_get(uuid) to service_role;
  grant execute on function public.cards_prefs_set(uuid, jsonb, timestamptz) to service_role;

  if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'cards_prefs' and not rowsecurity) then
    raise exception '107-prefs: cards_prefs has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_prefs' and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '107-prefs: cards_prefs is granted to a browser role';
  end if;

  notify pgrst, 'reload schema';
end $c107$;

-- ==== 9/15: 108-push.sql (verbatim) ====
-- 108-push.sql (Bunnyverse Cards lot 4, lane PUSH, 2026-11-13; the "Notify me" of the packs page)
--
-- What:   creates public.cards_push_subs, the web push subscriptions of the players (one row a browser: user, endpoint, keys, created,
--         last_sent_day, failures), with row level security on and NO grant for the browser roles, and 5 security definer functions
--         for the server (the service role only):
--           cards_push_upsert(user, endpoint, p256dh, auth, now)   stores or refreshes one subscription (at most 5 a player, the oldest goes)
--           cards_push_delete(user, endpoint)                      the player turns it off
--           cards_push_drop(endpoint)                              the push service answered 404 or 410: the subscription is gone for good
--           cards_push_result(id, ok)                              the cron's verdict on one send (failures back to 0, or plus 1)
--           cards_push_pick(now, limit)                            the cron's pick-and-mark: the rows to notify, marked in the same statement
-- Why:    one push at most when the stack becomes full (5 packs), never between 22:00 and 08:00 Paris (the reminder waits for 08:00), at most
--         one a Paris day for a player. The pick holds the rule so two cron runs never send twice: it locks the rows it takes (for update
--         skip locked) and marks them (last_sent_day, notified_anchor) in that same statement.
-- Full:   "full" is the stack cap the wallet reports in its 'cap' key (10 from file 110, 5 before it; a wallet without the key reads 5).
--         "becomes full" reads the wallet of 002: the stored row (cards_wallets) is below 5 while cards_wallet, which applies the refill and the
--         Paris midnight, now says 5. notified_anchor keeps the stored anchor of the notified cycle, so a stack that stays full is told once;
--         the next pack the player opens moves the anchor and re-arms it. A player without a wallet row (no pack opened yet) is never told.
--         A subscription made while the stack is already full starts notified for that cycle (no push for a stack that was full before).
-- Rows:   0 rows. 1 table, 2 indexes besides the keys, 5 functions. Additive: no existing table or function is touched.
-- Needs:  001 (cards_wallets) and 002 (cards_wallet).
-- Verify: select count(*) from information_schema.tables where table_schema = 'public' and table_name = 'cards_push_subs';   expect 1
-- Verify: select relrowsecurity from pg_class where oid = 'public.cards_push_subs'::regclass;   expect t
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_push_subs' and grantee in ('anon', 'authenticated');   expect 0
-- Verify: select count(*) from pg_policies where schemaname = 'public' and tablename = 'cards_push_subs';   expect 0
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname like 'cards\_push\_%';   expect 5
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_push\_%';   expect f
-- Verify: select bool_and(has_function_privilege('service_role', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_push\_%';   expect t
-- Verify: select count(*) from public.cards_push_subs;   expect 0 (on the first run)
-- Undo:   108-push.rollback.sql (drops the 5 functions and the table, and with it every subscription).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c108$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_wallets') is null or to_regprocedure('public.cards_wallet(uuid, timestamptz, integer, integer)') is null then
    raise exception '108-push: run 001-schema.sql and 002-functions.sql first';
  end if;

  create table if not exists public.cards_push_subs (
    id uuid constraint cards_push_subs_pkey primary key default gen_random_uuid(),
    user_id uuid not null constraint cards_push_subs_user_id_fkey references auth.users(id) on delete cascade,
    endpoint text not null constraint cards_push_subs_endpoint_key unique
      constraint cards_push_subs_endpoint_check check (endpoint ~ '^https://' and length(endpoint) <= 2048),
    p256dh text constraint cards_push_subs_p256dh_check check (p256dh is null or length(p256dh) <= 256),
    auth text constraint cards_push_subs_auth_check check (auth is null or length(auth) <= 256),
    created_at timestamptz not null default now(),
    last_sent_day date,
    notified_anchor timestamptz,
    failures integer not null default 0 constraint cards_push_subs_failures_check check (failures >= 0)
  );
  alter table public.cards_push_subs enable row level security;
  revoke all on table public.cards_push_subs from public, anon, authenticated;
  grant all on table public.cards_push_subs to service_role;
  create index if not exists cards_push_subs_user_idx on public.cards_push_subs (user_id, created_at);
  create index if not exists cards_push_subs_day_idx on public.cards_push_subs (last_sent_day) where failures < 5;

  -- Stores or refreshes one subscription. The endpoint is the key: a browser that signs in as another account moves to that account. At most 5
  -- a player (the oldest go). Starts notified for the cycle when the stack is already full (see Full above).
  create or replace function public.cards_push_upsert(p_user uuid, p_endpoint text, p_p256dh text, p_auth text, p_now timestamptz default now())
    returns boolean
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_full boolean := false;
  begin
    if p_user is null or p_endpoint is null or p_endpoint !~ '^https://' or length(p_endpoint) > 2048 then
      raise exception 'cards: push_endpoint';
    end if;
    select * into w from public.cards_wallets where user_id = p_user;
    if found then
      v_full := coalesce((select (q.x ->> 'stock')::integer >= coalesce((q.x ->> 'cap')::integer, 5) from (select public.cards_wallet(p_user, p_now) as x) q), false);
    end if;
    insert into public.cards_push_subs (user_id, endpoint, p256dh, auth, created_at, notified_anchor)
      values (p_user, p_endpoint, p_p256dh, p_auth, p_now, case when v_full then w.anchor else null end)
      on conflict (endpoint) do update
        set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth, failures = 0,
            notified_anchor = case when public.cards_push_subs.user_id = excluded.user_id then public.cards_push_subs.notified_anchor else excluded.notified_anchor end,
            last_sent_day = case when public.cards_push_subs.user_id = excluded.user_id then public.cards_push_subs.last_sent_day else null end;
    delete from public.cards_push_subs s
      where s.user_id = p_user
        and s.id in (select o.id from public.cards_push_subs o where o.user_id = p_user order by o.created_at desc, o.id offset 5);
    return true;
  end
  $f$;

  create or replace function public.cards_push_delete(p_user uuid, p_endpoint text)
    returns boolean
    language plpgsql security definer set search_path = public
    as $f$
  declare
    n integer;
  begin
    delete from public.cards_push_subs where user_id = p_user and endpoint = p_endpoint;
    get diagnostics n = row_count;
    return n > 0;
  end
  $f$;

  create or replace function public.cards_push_drop(p_endpoint text)
    returns boolean
    language plpgsql security definer set search_path = public
    as $f$
  declare
    n integer;
  begin
    delete from public.cards_push_subs where endpoint = p_endpoint;
    get diagnostics n = row_count;
    return n > 0;
  end
  $f$;

  create or replace function public.cards_push_result(p_id uuid, p_ok boolean)
    returns void
    language sql security definer set search_path = public
    as $f$
      update public.cards_push_subs set failures = case when p_ok then 0 else failures + 1 end where id = p_id
    $f$;

  -- The cron's pick-and-mark. Nothing between 22:00 and 08:00 Paris. A row is due when its player's stored stack is below 5 and cards_wallet (the
  -- refill and the Paris midnight applied) says 5, the cycle (the stored anchor) was not told yet, the player was told no push today, and the row
  -- failed fewer than 5 times in a row. The rows are locked and marked in the same statement: a second run skips them, or no longer sees them.
  create or replace function public.cards_push_pick(p_now timestamptz default now(), p_limit integer default 100)
    returns table (id uuid, user_id uuid, endpoint text)
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_local timestamp := p_now at time zone 'Europe/Paris';
    v_today date := (p_now at time zone 'Europe/Paris')::date;
  begin
    if extract(hour from v_local) >= 22 or extract(hour from v_local) < 8 then
      return;
    end if;
    return query
      with due as (
        select s.id as sid
        from public.cards_push_subs s
        join public.cards_wallets w on w.user_id = s.user_id
        where s.failures < 5
          and s.last_sent_day is distinct from v_today
          and s.notified_anchor is distinct from w.anchor
          and w.stock < coalesce((public.cards_wallet(s.user_id, p_now) ->> 'cap')::integer, 5)
          and not exists (select 1 from public.cards_push_subs o where o.user_id = s.user_id and o.last_sent_day = v_today)
          and (public.cards_wallet(s.user_id, p_now) ->> 'stock')::integer >= coalesce((public.cards_wallet(s.user_id, p_now) ->> 'cap')::integer, 5)
        order by s.created_at, s.id
        limit greatest(1, least(coalesce(p_limit, 100), 500))
        for update of s skip locked
      )
      update public.cards_push_subs u
        set last_sent_day = v_today, notified_anchor = (select w2.anchor from public.cards_wallets w2 where w2.user_id = u.user_id)
        from due
        where u.id = due.sid
        returning u.id, u.user_id, u.endpoint;
  end
  $f$;

  revoke all on function public.cards_push_upsert(uuid, text, text, text, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_push_delete(uuid, text) from public, anon, authenticated;
  revoke all on function public.cards_push_drop(text) from public, anon, authenticated;
  revoke all on function public.cards_push_result(uuid, boolean) from public, anon, authenticated;
  revoke all on function public.cards_push_pick(timestamptz, integer) from public, anon, authenticated;
  grant execute on function public.cards_push_upsert(uuid, text, text, text, timestamptz) to service_role;
  grant execute on function public.cards_push_delete(uuid, text) to service_role;
  grant execute on function public.cards_push_drop(text) to service_role;
  grant execute on function public.cards_push_result(uuid, boolean) to service_role;
  grant execute on function public.cards_push_pick(timestamptz, integer) to service_role;

  notify pgrst, 'reload schema';
end $c108$;

-- ==== 10/15: 110-core.sql (verbatim) ====
-- 110-core.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; the stack of 10, the themes, the golden pack, Open 5 in ONE transaction, locks, recycle, craft)
--
-- What:   in ONE DO block:
--           columns  cards_wallets.packs_opened, seen_at, created_at   the player's pack count, the last action (the "still there?" check), the start
--                    cards_packs.seq, theme, golden, guarantee, batch   the pack number, what it was opened as, the golden and guarantee flags, the Open 5 batch
--                    cards_owned.locked, seen                          a locked card is never recycled; seen=false is the "New" badge
--           constraint cards_packs_source_check   now also 'daily'
--           table    cards_group_types    the type of a group (girl, boy, mixed) with the two sources it was checked against (filled by 111)
--           new functions
--                    cards_theme_of(entity)             'girls', 'boys', 'solo' or null: the theme packs a subject belongs to
--                    cards_in_pool(card, kind, group)   true when a card is in packs, with an active entity, and in the pool of a pack kind
--                    cards_pool_has(kind, group, rarities)  true when that pool has a card of one of the rarities
--                    cards_daily_group(day)             the pack of the day: one group a day, by the Paris day number
--                    cards_open(...)                    ONE function, ONE transaction: 1 or 5 packs, wallet locked, idempotency key, audit; sources stock, daily, focus,
--                                                       shards and bonus (the Kpopdle bonus pack of 002, still earned by a win decided in the database)
--                    cards_recycle(user, key, n, now, timer_cap)   bulk (locked cards and Gold and Full Art extras never) or one extra copy
--                    cards_lock(user, card, on, now)    lock or unlock an owned card
--                    cards_seen(user, cards)            clears the New badge
--                    cards_still_there(user, now, timer_cap)   the quiet check: restarts a paused timer, takes nothing
--                    cards_player(user, now)            everything the lobby needs about a player in one answer
--           replaced functions (old signature dropped, one of each name remains)
--                    cards_roll        stack cap 10 (parameter), the pause after 2 hours without an action
--                    cards_wallet      adds cap, paused, packs_opened, seen_at
--                    cards_pity_count  orders by the pack number, so the packs of one Open 5 are counted pack by pack
--                    cards_craft       takes an idempotency key, writes the audit, leaves the New badge on
--                    cards_ad_grant    takes an idempotency key, writes the audit
--           dropped  cards_apply_pack  (the old one-pack function; cards_open replaces it)
-- Why:    the owner's rules of the v6 prototype: a stack of 10, a pack every 10 minutes, at most 40 timer packs a Paris day (the midnight top-up is
--         not counted), a golden pack every 10th pack (card 5 Holo or better), the Gold guarantee by pack 30, the themes All idols, Girl groups,
--         Boy groups and Soloists, a pack of the day (one group a day, free once), the focus pack, Open 5 (five packs, 25 cards, one transaction),
--         locks, recycling with safeguards. The DRAW stays in TypeScript with crypto.randomInt (lib/kpopcards/draw.ts); the database only
--         CHOOSES between the candidates the server drew, by rules that depend on the player's state at the moment of the lock: for each pack the
--         server sends the five plain cards plus a golden fifth card and a Gold fifth card, and cards_open takes the plain one, the golden one or
--         the Gold one according to the pack number and the guarantee COUNTED INSIDE THE TRANSACTION, then swaps a group half for its other half
--         when the player owns exactly one. So ten openings in parallel on one account cannot break a promise, whatever order they land in.
-- Rows:   0 rows changed except 3 backfills of new columns (packs_opened and seq from the player's packs, created_at from the first card), all
--         idempotent. 1 table, 9 columns, 10 new functions, 5 replaced, 1 dropped. No XP, level, streak or badge of kpopquiz.org is touched.
-- Needs:  001, 002, 102 (cards_catalog.part), 104, 105 (ledgers) and 107 (preferences).
-- Errors: words after "cards: ": bonus (no Kpopdle bonus pack to open), empty, stack_short, shards, daily_used, focus_used, focus, pack, source, theme, key, idem_conflict, locked,
--         lastcopy, nothing, notowned, owned, card, no_craft, ad_limit, ticket, user.
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_theme_of', 'cards_in_pool', 'cards_pool_has', 'cards_daily_group', 'cards_open', 'cards_recycle', 'cards_lock', 'cards_seen', 'cards_still_there', 'cards_player');   expect 10
-- Verify: select proname, count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_roll', 'cards_wallet', 'cards_pity_count', 'cards_craft', 'cards_ad_grant', 'cards_open') group by proname order by proname;   expect each 1
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_apply_pack';   expect 0
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_%';   expect f
-- Verify: select count(*) from pg_tables where schemaname = 'public' and tablename = 'cards_group_types' and rowsecurity;   expect 1
-- Verify: select (public.cards_wallet('00000000-0000-0000-0000-000000000000', '2026-11-12 10:00+00')) ->> 'cap';   expect 10
-- Verify: select count(*) from public.cards_wallets where packs_opened <> (select count(*) from public.cards_packs p where p.user_id = cards_wallets.user_id);   expect 0
-- Undo:   110-core.rollback.sql (refused while an Open 5 batch, a daily pack, a lock or a ledger row of 110 exists)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c110$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_wallets') is null or to_regclass('public.cards_catalog') is null or to_regclass('public.cards_packs') is null
     or to_regclass('public.cards_owned') is null or to_regclass('public.cards_entities') is null then
    raise exception '110-core: run 001-schema.sql first';
  end if;
  if to_regclass('public.cards_idem') is null or to_regclass('public.cards_audit') is null then
    raise exception '110-core: run 105-goals.sql first (the idempotency ledger)';
  end if;
  if to_regclass('public.cards_prefs') is null then
    raise exception '110-core: run 107-prefs.sql first';
  end if;
  if to_regprocedure('public.cards_craft(uuid, integer, timestamptz)') is null and to_regprocedure('public.cards_craft(uuid, text, integer, timestamptz, integer)') is null then
    raise exception '110-core: run 104-economy.sql first';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_catalog' and column_name = 'part') then
    raise exception '110-core: run 102-catalog-rebuild.sql first (cards_catalog.part)';
  end if;

  -- ---------- columns ----------
  alter table public.cards_wallets add column if not exists packs_opened integer not null default 0;
  alter table public.cards_wallets add column if not exists seen_at timestamptz not null default now();
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_wallets' and column_name = 'created_at') then
    alter table public.cards_wallets add column created_at timestamptz not null default now();
    update public.cards_wallets w set created_at = least(w.updated_at, coalesce((select min(o.first_at) from public.cards_owned o where o.user_id = w.user_id), w.updated_at));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cards_wallets_packs_opened_check' and conrelid = 'public.cards_wallets'::regclass) then
    alter table public.cards_wallets add constraint cards_wallets_packs_opened_check check (packs_opened >= 0);
  end if;

  alter table public.cards_packs add column if not exists seq integer;
  alter table public.cards_packs add column if not exists theme text;
  alter table public.cards_packs add column if not exists golden boolean not null default false;
  alter table public.cards_packs add column if not exists guarantee boolean not null default false;
  alter table public.cards_packs add column if not exists batch uuid;
  if not exists (select 1 from pg_constraint where conname = 'cards_packs_theme_check' and conrelid = 'public.cards_packs'::regclass) then
    alter table public.cards_packs add constraint cards_packs_theme_check check (theme is null or theme in ('all', 'girls', 'boys', 'solo', 'daily', 'focus'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cards_packs_source_check' and conrelid = 'public.cards_packs'::regclass and pg_get_constraintdef(oid) like '%daily%') then
    alter table public.cards_packs drop constraint if exists cards_packs_source_check;
    alter table public.cards_packs add constraint cards_packs_source_check check (source in ('stock', 'ad', 'shards', 'bonus', 'daily'));
  end if;
  create index if not exists cards_packs_seq_idx on public.cards_packs (user_id, seq desc nulls last);

  -- The pack number of every older pack, oldest first, and each wallet's count. Only the rows that have none yet.
  update public.cards_packs p set seq = x.rn
    from (select id, row_number() over (partition by user_id order by opened_at, id) as rn from public.cards_packs) x
   where p.id = x.id and p.seq is null;
  update public.cards_wallets w set packs_opened = c.n
    from (select user_id, count(*)::integer as n from public.cards_packs group by user_id) c
   where c.user_id = w.user_id and w.packs_opened = 0 and c.n > 0;

  alter table public.cards_owned add column if not exists locked boolean not null default false;
  alter table public.cards_owned add column if not exists seen boolean not null default true;

  create table if not exists public.cards_group_types (
    entity_id text constraint cards_group_types_pkey primary key constraint cards_group_types_entity_id_fkey references public.cards_entities(id) on delete cascade,
    gender text not null constraint cards_group_types_gender_check check (gender in ('girl', 'boy', 'mixed')),
    source_a text not null,
    source_b text not null,
    checked_on date not null
  );
  alter table public.cards_group_types enable row level security;
  revoke all on table public.cards_group_types from public, anon, authenticated;
  grant all on table public.cards_group_types to service_role;

  -- ---------- the theme of a subject ----------
  -- A group is 'girls' or 'boys' by cards_group_types ('mixed' and unknown groups belong to no themed pack, only to All idols). An idol takes its
  -- group's theme; an idol with no group, or whose group has no card of its own in packs (as in the sets of 105), is a soloist.
  create or replace function public.cards_theme_of(p_entity text)
    returns text
    language sql stable security definer set search_path = public
    as $f$
      select case
        when e.kind = 'group' then (select case t.gender when 'girl' then 'girls' when 'boy' then 'boys' else null end from public.cards_group_types t where t.entity_id = e.id)
        when e.kind = 'idol' and (e.group_id is null or not exists (
               select 1 from public.cards_catalog c join public.cards_entities g on g.id = c.entity_id
                where c.in_packs and g.active and g.id = e.group_id and g.kind = 'group'))
          then 'solo'
        when e.kind = 'idol' then (select case t.gender when 'girl' then 'girls' when 'boy' then 'boys' else null end from public.cards_group_types t where t.entity_id = e.group_id)
        else null end
        from public.cards_entities e where e.id = p_entity
    $f$;

  -- A card is in the pool of a pack kind: 'all' (any card in packs), 'girls' | 'boys' | 'solo' (its subject's theme), 'daily' (the group p_group:
  -- its own cards and its idols').
  create or replace function public.cards_in_pool(p_card integer, p_kind text, p_group text default null)
    returns boolean
    language sql stable security definer set search_path = public
    as $f$
      select exists (
        select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
         where c.card_no = p_card and c.in_packs and e.active
           and case p_kind
                 when 'all' then true
                 when 'daily' then (c.entity_id = p_group or e.group_id = p_group)
                 when 'girls' then public.cards_theme_of(c.entity_id) = 'girls'
                 when 'boys' then public.cards_theme_of(c.entity_id) = 'boys'
                 when 'solo' then public.cards_theme_of(c.entity_id) = 'solo'
                 else false end)
    $f$;

  create or replace function public.cards_pool_has(p_kind text, p_group text, p_rarities text[])
    returns boolean
    language sql stable security definer set search_path = public
    as $f$
      select exists (
        select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
         where c.in_packs and e.active and c.rarity = any (p_rarities)
           and case p_kind
                 when 'all' then true
                 when 'daily' then (c.entity_id = p_group or e.group_id = p_group)
                 when 'girls' then public.cards_theme_of(c.entity_id) = 'girls'
                 when 'boys' then public.cards_theme_of(c.entity_id) = 'boys'
                 when 'solo' then public.cards_theme_of(c.entity_id) = 'solo'
                 else false end)
    $f$;

  -- The pack of the day: the groups with a card of their own in packs, ordered by id, indexed by the number of days since 1970-01-01 of the Paris day.
  create or replace function public.cards_daily_group(p_day date)
    returns text
    language sql stable security definer set search_path = public
    as $f$
      with g as (
        select e.id, row_number() over (order by e.id collate "C") - 1 as i, count(*) over () as n
          from public.cards_entities e
         where e.kind = 'group' and e.active
           and exists (select 1 from public.cards_catalog c where c.in_packs and c.entity_id = e.id))
      select g.id from g where g.i = (((p_day - date '1970-01-01') % g.n) + g.n) % g.n
    $f$;

  -- ---------- the refill: cap 10, pause after 2 hours without an action ----------
  drop function if exists public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer);
  create or replace function public.cards_roll(
      p_stock integer, p_anchor timestamptz, p_day date, p_ads integer, p_bonus integer, p_now timestamptz,
      p_timer integer default 0, p_timer_cap integer default 40, p_cap integer default 10, p_pause_at timestamptz default null)
    returns jsonb
    language plpgsql stable set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_stock integer := p_stock;
    v_anchor timestamptz := p_anchor;
    v_ads integer := p_ads;
    v_bonus integer := p_bonus;
    v_timer integer := coalesce(p_timer, 0);
    v_clock timestamptz := case when p_pause_at is null then p_now else least(p_now, p_pause_at) end;
    v_paused boolean := false;
    k bigint;
    g integer;
    v_room integer;
  begin
    if p_day is distinct from v_today then
      v_ads := 0;
      v_bonus := 0;
      v_timer := 0;
      if v_stock < p_cap then
        v_stock := p_cap;
        v_anchor := p_now;
      end if;
    end if;
    if v_stock >= p_cap then
      v_anchor := p_now;
    else
      k := floor(extract(epoch from (v_clock - v_anchor)) / 600);
      v_room := greatest(0, p_timer_cap - v_timer);
      if k > 0 and v_room > 0 then
        g := least(k, p_cap - v_stock, v_room);
        v_stock := v_stock + g;
        v_timer := v_timer + g;
        if v_stock >= p_cap then
          v_anchor := p_now;
        elsif g = v_room then
          v_anchor := v_anchor + make_interval(secs => (g * 600)::double precision);
        else
          v_anchor := v_anchor + make_interval(secs => (k * 600)::double precision);
        end if;
      end if;
      -- Paused: the player did nothing for 2 hours, so the timer stopped at p_pause_at and waits for him (nothing is taken).
      v_paused := p_pause_at is not null and p_now > p_pause_at and v_stock < p_cap and v_timer < p_timer_cap;
    end if;
    return jsonb_build_object('stock', v_stock, 'anchor', v_anchor, 'paris_day', v_today, 'ads_today', v_ads, 'bonus_today', v_bonus, 'timer_today', v_timer, 'paused', v_paused);
  end
  $f$;

  -- Packs in a row, newest first, with no Gold and no Full Art card; at most 30 are read. Any source counts. Ordered by the pack number, so the
  -- packs of one Open 5 (same opened_at) count in the order they were opened.
  create or replace function public.cards_pity_count(p_user uuid)
    returns integer
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    r record;
    n integer := 0;
  begin
    for r in select p.cards from public.cards_packs p where p.user_id = p_user order by p.seq desc nulls last, p.opened_at desc, p.id desc limit 30 loop
      exit when exists (select 1 from public.cards_catalog c where c.card_no = any (r.cards) and c.rarity in ('UR', 'L'));
      n := n + 1;
    end loop;
    return n;
  end
  $f$;

  -- ---------- the wallet, read only ----------
  drop function if exists public.cards_wallet(uuid, timestamptz, integer, integer, integer);
  create or replace function public.cards_wallet(
      p_user uuid, p_now timestamptz default now(), p_ads_limit integer default 10, p_bonus_cap integer default 3, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_stock integer;
    v_anchor timestamptz;
    v_bonus_seen integer;
    v_timer integer;
    v_paused boolean;
  begin
    select * into w from public.cards_wallets where user_id = p_user;
    if not found then
      w.stock := 10; w.anchor := p_now; w.paris_day := v_today; w.ads_today := 0; w.bonus_today := 0; w.shards := 0; w.timer_today := 0;
      w.packs_opened := 0; w.seen_at := p_now;
    end if;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    v_stock := (r ->> 'stock')::integer;
    v_anchor := (r ->> 'anchor')::timestamptz;
    v_timer := (r ->> 'timer_today')::integer;
    v_paused := (r ->> 'paused')::boolean;
    v_bonus_seen := case when p_bonus_cap <= 0 then 0 else public.cards_bonus_plays(p_user, v_today) end;
    return jsonb_build_object(
      'stock', v_stock,
      'cap', 10,
      'anchor', v_anchor,
      'paris_day', v_today,
      'ads_today', (r ->> 'ads_today')::integer,
      'bonus_today', (r ->> 'bonus_today')::integer,
      'shards', w.shards,
      'ads_left', greatest(0, p_ads_limit - (r ->> 'ads_today')::integer),
      'bonus_left', greatest(0, least(p_bonus_cap, v_bonus_seen) - (r ->> 'bonus_today')::integer),
      'next_at', case when v_stock >= 10 or v_timer >= p_timer_cap or v_paused then null else v_anchor + interval '600 seconds' end,
      'midnight_at', ((v_today + 1)::timestamp at time zone 'Europe/Paris'),
      'timer_used', v_timer,
      'timer_cap', p_timer_cap,
      'timer_left', greatest(0, p_timer_cap - v_timer),
      'paused', v_paused,
      'seen_at', w.seen_at,
      'packs_opened', w.packs_opened,
      'pity_left', case when public.cards_pity_pool() then greatest(1, 30 - public.cards_pity_count(p_user)) else null end,
      'focus_used', public.cards_focus_used(p_user, p_now));
  end
  $f$;

  -- Everything the lobby needs about a player in one answer (read only). Lists are small: a binder is a few hundred cards.
  create or replace function public.cards_player(p_user uuid, p_now timestamptz default now(), p_timer_cap integer default 40)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
  begin
    select * into w from public.cards_wallets where user_id = p_user;
    if not found then
      w.stock := 10; w.anchor := p_now; w.paris_day := v_today; w.ads_today := 0; w.bonus_today := 0; w.shards := 0; w.timer_today := 0;
      w.packs_opened := 0; w.seen_at := p_now; w.created_at := p_now;
    end if;
    return jsonb_build_object(
      'wallet', jsonb_build_object('stock', w.stock, 'anchor', w.anchor, 'paris_day', w.paris_day, 'ads_today', w.ads_today, 'timer_today', w.timer_today,
                                   'shards', w.shards, 'packs_opened', w.packs_opened, 'seen_at', w.seen_at, 'created_at', w.created_at),
      'owned', coalesce((select jsonb_agg(jsonb_build_object('n', o.card_no, 'copies', o.copies, 'fav', o.favorite, 'locked', o.locked, 'seen', o.seen,
                                                              'first', o.first_at, 'last', o.last_at, 'fpn', o.first_pack_no) order by o.card_no)
                           from public.cards_owned o where o.user_id = p_user), '[]'::jsonb),
      'wishlist', coalesce((select jsonb_agg(x.card_no order by x.card_no) from public.cards_wishlist x where x.user_id = p_user), '[]'::jsonb),
      'gold_count', public.cards_pity_count(p_user),
      'claimed', coalesce((select jsonb_agg(c.set_id order by c.set_id) from public.cards_sets_claimed c where c.user_id = p_user), '[]'::jsonb),
      'week', public.cards_week_progress(p_user, p_now),
      'prefs', public.cards_prefs_get(p_user),
      'recent', public.cards_recent_packs(p_user, 10),
      'bonus_earned', public.cards_bonus_plays(p_user, v_today),
      'bonus_today', case when w.paris_day = v_today then w.bonus_today else 0 end,
      'daily_used', exists (select 1 from public.cards_packs p where p.user_id = p_user and p.source = 'daily'
                             and p.opened_at >= v_today::timestamp at time zone 'Europe/Paris' and p.opened_at < (v_today + 1)::timestamp at time zone 'Europe/Paris'),
      'focus_used', public.cards_focus_used(p_user, p_now),
      'last', (select jsonb_build_object('at', p.opened_at, 'pack_no', coalesce(p.seq, 0), 'cards', p.cards)
                 from public.cards_packs p where p.user_id = p_user order by p.seq desc nulls last, p.opened_at desc, p.id desc limit 1),
      'new_in_last', (select coalesce(p.new_count, 0) from public.cards_packs p where p.user_id = p_user order by p.seq desc nulls last, p.opened_at desc, p.id desc limit 1));
  end
  $f$;

  -- ---------- the openings ----------
  drop function if exists public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer, integer, text);

  -- p_draws: a jsonb array of 1 or 5 objects {"c": [5 card numbers], "g": golden fifth card or null, "u": Gold fifth card or null}. All of it was
  -- drawn on the server with crypto.randomInt; this function only chooses among it, by the rules of the player's state under the lock.
  create or replace function public.cards_open(
      p_user uuid, p_key text, p_source text, p_theme text, p_focus text, p_draws jsonb, p_now timestamptz default now(),
      p_ads_limit integer default 10, p_bonus_cap integer default 3, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_n integer;
    v_op text;
    v_hit public.cards_idem%rowtype;
    v_kind text;
    v_theme text;
    v_group text;
    v_stock integer;
    v_anchor timestamptz;
    v_ads integer;
    v_bonus integer;
    v_timer integer;
    v_shards integer;
    v_packs_opened integer;
    v_batch uuid := gen_random_uuid();
    v_i integer;
    v_k integer;
    v_packno integer;
    v_golden boolean;
    v_pity boolean;
    v_cards integer[];
    v_card integer;
    v_pick integer;
    v_c record;
    v_p record;
    v_g integer;
    v_u integer;
    v_new boolean;
    v_pair boolean;
    v_newn integer;
    v_seen integer[];
    v_pack uuid;
    v_out jsonb := '[]'::jsonb;
    v_cards_out jsonb;
    v_pack_ids jsonb := '[]'::jsonb;
    v_before_ids text[];
    v_after_ids text[];
    v_fin jsonb;
    v_owned_before integer;
    v_owned_after integer;
    v_res jsonb;
    v_own_c boolean;
    v_own_p boolean;
    v_best text;
    v_have_hi boolean;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    if p_source is null or p_source not in ('stock', 'daily', 'focus', 'shards', 'bonus') then raise exception 'cards: source'; end if;
    if p_draws is null or jsonb_typeof(p_draws) <> 'array' then raise exception 'cards: pack'; end if;
    v_n := jsonb_array_length(p_draws);
    if v_n not in (1, 5) or (v_n = 5 and p_source <> 'stock') then raise exception 'cards: pack'; end if;
    v_theme := case when p_source in ('stock', 'shards', 'bonus') then coalesce(p_theme, 'all') else null end;
    if v_theme is not null and v_theme not in ('all', 'girls', 'boys', 'solo') then raise exception 'cards: theme'; end if;
    v_op := 'open:' || p_source || ':' || v_n || ':' || coalesce(v_theme, '') || ':' || coalesce(p_focus, '');

    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;

    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> v_op then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;

    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    v_stock := (r ->> 'stock')::integer;
    v_anchor := case when (r ->> 'paused')::boolean then p_now else (r ->> 'anchor')::timestamptz end;
    v_ads := (r ->> 'ads_today')::integer;
    v_bonus := (r ->> 'bonus_today')::integer;
    v_timer := (r ->> 'timer_today')::integer;
    v_shards := w.shards;

    if p_source = 'stock' then
      if v_stock < v_n then raise exception '%', case when v_n = 1 then 'cards: empty' else 'cards: stack_short' end; end if;
      v_stock := v_stock - v_n;
      v_kind := v_theme;
    elsif p_source = 'shards' then
      if v_shards < 50 then raise exception 'cards: shards'; end if;
      v_shards := v_shards - 50;
      v_kind := v_theme;
    elsif p_source = 'bonus' then
      -- The Kpopdle bonus pack (002's rule, unchanged): earned by a win decided in the database and recorded once per play in cards_bonus_earned,
      -- at most p_bonus_cap a Paris day (CARDS_BONUS_PER_DAY; 0 while the bridges are off). It does not touch the stack.
      if v_n <> 1 then raise exception 'cards: pack'; end if;
      if p_bonus_cap <= 0 or v_bonus >= least(p_bonus_cap, public.cards_bonus_plays(p_user, v_today)) then raise exception 'cards: bonus'; end if;
      v_bonus := v_bonus + 1;
      v_kind := v_theme;
    elsif p_source = 'daily' then
      if exists (select 1 from public.cards_packs p where p.user_id = p_user and p.source = 'daily'
                  and p.opened_at >= v_today::timestamp at time zone 'Europe/Paris' and p.opened_at < (v_today + 1)::timestamp at time zone 'Europe/Paris') then
        raise exception 'cards: daily_used';
      end if;
      v_group := public.cards_daily_group(v_today);
      if v_group is null then raise exception 'cards: pack'; end if;
      v_kind := 'daily';
    else
      if p_focus is null or not exists (select 1 from public.cards_entities where id = p_focus and kind = 'group' and active) then raise exception 'cards: focus'; end if;
      if v_stock < 1 then raise exception 'cards: empty'; end if;
      if public.cards_focus_used(p_user, p_now) then raise exception 'cards: focus_used'; end if;
      v_stock := v_stock - 1;
      v_kind := 'all';
      v_group := p_focus;
    end if;

    select count(*) into v_owned_before from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and c.in_packs;
    select coalesce(array_agg(x.set_id), '{}') into v_before_ids from public.cards_goals_progress(p_user, null) x where x.total > 0 and x.owned >= x.total and not x.claimed;

    v_packs_opened := w.packs_opened;
    for v_i in 1..v_n loop
      v_packno := v_packs_opened + v_i;
      v_golden := v_packno % 10 = 0;
      v_pity := public.cards_pity_count(p_user) >= 29 and public.cards_pity_pool();
      select array(select (e.value)::integer from jsonb_array_elements_text(p_draws -> (v_i - 1) -> 'c') e(value)) into v_cards;
      if cardinality(v_cards) <> 5 or array_position(v_cards, null) is not null then raise exception 'cards: pack'; end if;
      v_g := nullif(p_draws -> (v_i - 1) ->> 'g', '')::integer;
      v_u := nullif(p_draws -> (v_i - 1) ->> 'u', '')::integer;

      -- Card 5: the Gold card of the guarantee, else the golden pack's Holo-or-better card, else the plain fifth card (never Standard).
      if v_pity then
        if v_u is null then raise exception 'cards: pack'; end if;
        v_cards[5] := v_u;
      elsif v_golden then
        if v_g is null then raise exception 'cards: pack'; end if;
        v_cards[5] := v_g;
      end if;

      -- The checks: every card is in packs and in the pool of this pack kind (the guarantee and the golden rule may leave the pool only when the pool
      -- has no card to give), the fifth card is never Standard, a golden fifth card is Holo or better, a guaranteed one is Gold, a focus pack's
      -- cards 2 and 4 are the group's when the group has a card of their rarity.
      for v_k in 1..5 loop
        v_card := v_cards[v_k];
        select c.rarity, c.entity_id into v_c from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id where c.card_no = v_card and c.in_packs and e.active;
        if not found then raise exception 'cards: pack'; end if;
        if not public.cards_in_pool(v_card, v_kind, v_group) then
          if not (v_k = 5 and v_pity and v_c.rarity = 'UR' and not public.cards_pool_has(v_kind, v_group, array['UR']))
             and not (v_k = 5 and v_golden and not v_pity and v_c.rarity in ('R', 'SR', 'UR', 'L') and not public.cards_pool_has(v_kind, v_group, array['R', 'SR', 'UR', 'L'])) then
            raise exception 'cards: pack';
          end if;
        end if;
        if v_k = 5 then
          if v_c.rarity = 'C' then raise exception 'cards: pack'; end if;
          if v_pity and v_c.rarity <> 'UR' then raise exception 'cards: pack'; end if;
          if v_golden and not v_pity and v_c.rarity not in ('R', 'SR', 'UR', 'L') and public.cards_pool_has(v_kind, v_group, array['R', 'SR', 'UR', 'L']) then raise exception 'cards: pack'; end if;
        end if;
        if p_source = 'focus' and v_k in (2, 4) then
          if not exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id where c.card_no = v_card and (c.entity_id = p_focus or e.group_id = p_focus))
             and exists (select 1 from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
                          where c.rarity = v_c.rarity and c.in_packs and e.active and (c.entity_id = p_focus or e.group_id = p_focus)) then
            raise exception 'cards: pack';
          end if;
        end if;
      end loop;

      -- The pack: swap a group half for its other half when the player owns exactly one (cards of this pack stored before count), store, count.
      v_seen := '{}';
      v_newn := 0;
      v_cards_out := '[]'::jsonb;
      for v_k in 1..5 loop
        v_card := v_cards[v_k];
        select c.entity_id, c.rarity, c.part into v_c from public.cards_catalog c where c.card_no = v_card;
        if v_c.part in (1, 2) then
          select h.card_no into v_pick from public.cards_catalog h where h.entity_id = v_c.entity_id and h.rarity = v_c.rarity and h.part = 3 - v_c.part and h.in_packs;
          if v_pick is not null then
            v_own_c := exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_card);
            v_own_p := exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_pick);
            if v_own_c and not v_own_p then
              v_card := v_pick;
              v_cards[v_k] := v_pick;
              select c.entity_id, c.rarity, c.part into v_c from public.cards_catalog c where c.card_no = v_card;
            end if;
          end if;
        end if;
        v_new := not exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_card);
        v_pair := false;
        if v_new and v_c.part in (1, 2) then
          v_pair := exists (select 1 from public.cards_catalog h join public.cards_owned o on o.card_no = h.card_no and o.user_id = p_user
                             where h.entity_id = v_c.entity_id and h.rarity = v_c.rarity and h.part = 3 - v_c.part);
        end if;
        if v_new then v_newn := v_newn + 1; end if;
        insert into public.cards_owned as o (user_id, card_no, copies, first_at, last_at, first_pack_no, first_source, seen)
        values (p_user, v_card, 1, p_now, p_now, v_packno, 'pack', false)
        on conflict (user_id, card_no) do update set copies = o.copies + 1, last_at = p_now;
        v_cards_out := v_cards_out || jsonb_build_array(jsonb_build_object('n', v_card, 'isNew', v_new, 'completesPair', v_pair,
                                                                           'golden', v_k = 5 and v_golden, 'guarantee', v_k = 5 and v_pity));
      end loop;
      delete from public.cards_wishlist where user_id = p_user and card_no = any (v_cards);

      insert into public.cards_packs (user_id, source, cards, opened_at, focus, new_count, seq, theme, golden, guarantee, batch)
      values (p_user, case when p_source = 'focus' then 'stock' else p_source end, v_cards, p_now, case when p_source = 'focus' then p_focus else null end,
              v_newn, v_packno, case when p_source = 'daily' then 'daily' when p_source = 'focus' then 'focus' else v_theme end, v_golden, v_pity,
              case when v_n > 1 then v_batch else null end)
      returning id into v_pack;
      v_pack_ids := v_pack_ids || to_jsonb(v_pack::text);
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'id', v_pack, 'pack_no', v_packno, 'source', p_source, 'theme', case when p_source = 'daily' then 'daily' when p_source = 'focus' then 'focus' else v_theme end,
        'group', v_group, 'golden', v_golden, 'guarantee', v_pity, 'cards', v_cards_out, 'new_count', v_newn));
    end loop;

    select count(*) into v_owned_after from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and c.in_packs;
    select coalesce(array_agg(x.set_id), '{}') into v_after_ids from public.cards_goals_progress(p_user, null) x where x.total > 0 and x.owned >= x.total and not x.claimed;
    select coalesce(jsonb_agg(jsonb_build_object('id', x.set_id, 'name', coalesce(x.name, case x.kind when 'solo' then 'Soloists' when 'holo' then 'Every Holo card' when 'gold' then 'Every Gold card' else 'Debut ' || x.name end), 'packs', x.packs)
                             order by x.set_id), '[]'::jsonb)
      into v_fin from public.cards_goals_progress(p_user, null) x
     where x.set_id = any (v_after_ids) and not (x.set_id = any (v_before_ids));

    update public.cards_wallets
       set stock = v_stock, anchor = v_anchor, paris_day = v_today, ads_today = v_ads, bonus_today = v_bonus, timer_today = v_timer, shards = v_shards,
           packs_opened = packs_opened + v_n, seen_at = p_now, version = version + 1, updated_at = p_now
     where user_id = p_user;

    v_res := jsonb_build_object('replayed', false, 'packs', v_out, 'finished', v_fin, 'owned_before', v_owned_before, 'owned_after', v_owned_after);
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, v_op, v_res, p_now);
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at)
    values (p_user, 'open', p_key, jsonb_build_object('source', p_source, 'theme', v_theme, 'focus', p_focus, 'packs', v_pack_ids, 'batch', case when v_n > 1 then v_batch else null end,
                                                       'stock_after', v_stock, 'shards_after', v_shards), p_now);
    return v_res;
  end
  $f$;

  -- ---------- craft ----------
  drop function if exists public.cards_craft(uuid, integer, timestamptz);
  create or replace function public.cards_craft(p_user uuid, p_key text, p_card_no integer, p_now timestamptz default now(), p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_rarity text;
    v_cost integer;
    v_packno integer;
    v_hit public.cards_idem%rowtype;
    v_op text := 'craft:' || coalesce(p_card_no::text, '');
    v_before text[];
    v_after text[];
    v_fin jsonb;
    v_out jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    select c.rarity into v_rarity
      from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
     where c.card_no = p_card_no and c.in_packs and e.active;
    if v_rarity is null then raise exception 'cards: card'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> v_op then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;
    if v_rarity = 'L' then raise exception 'cards: no_craft'; end if;
    v_cost := case v_rarity when 'C' then 10 when 'U' then 20 when 'R' then 50 when 'SR' then 120 else 300 end;
    if exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = p_card_no) then raise exception 'cards: owned'; end if;
    if w.shards < v_cost then raise exception 'cards: shards'; end if;

    select coalesce(array_agg(x.set_id), '{}') into v_before from public.cards_goals_progress(p_user, null) x where x.total > 0 and x.owned >= x.total and not x.claimed;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    v_packno := w.packs_opened;
    update public.cards_wallets
       set shards = shards - v_cost, stock = (r ->> 'stock')::integer, anchor = case when (r ->> 'paused')::boolean then p_now else (r ->> 'anchor')::timestamptz end,
           paris_day = v_today, ads_today = (r ->> 'ads_today')::integer, bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           seen_at = p_now, version = version + 1, updated_at = p_now
     where user_id = p_user;
    insert into public.cards_owned (user_id, card_no, copies, first_at, last_at, first_pack_no, first_source, seen)
    values (p_user, p_card_no, 1, p_now, p_now, v_packno, 'craft', false);
    insert into public.cards_crafts (user_id, card_no, rarity, cost, crafted_at) values (p_user, p_card_no, v_rarity, v_cost, p_now);
    delete from public.cards_wishlist where user_id = p_user and card_no = p_card_no;
    select coalesce(array_agg(x.set_id), '{}') into v_after from public.cards_goals_progress(p_user, null) x where x.total > 0 and x.owned >= x.total and not x.claimed;
    select coalesce(jsonb_agg(jsonb_build_object('id', x.set_id, 'name', coalesce(x.name, case x.kind when 'solo' then 'Soloists' when 'holo' then 'Every Holo card' when 'gold' then 'Every Gold card' else 'Debut ' || x.name end), 'packs', x.packs)
                             order by x.set_id), '[]'::jsonb)
      into v_fin from public.cards_goals_progress(p_user, null) x where x.set_id = any (v_after) and not (x.set_id = any (v_before));
    v_out := jsonb_build_object('replayed', false, 'card_no', p_card_no, 'rarity', v_rarity, 'cost', v_cost, 'shards', w.shards - v_cost, 'finished', v_fin);
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, v_op, v_out, p_now);
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at) values (p_user, 'craft', p_key, jsonb_build_object('card_no', p_card_no, 'cost', v_cost), p_now);
    return v_out;
  end
  $f$;

  -- ---------- the rewarded ad ----------
  drop function if exists public.cards_ad_grant(uuid, uuid, timestamptz, integer, integer, integer);
  create or replace function public.cards_ad_grant(
      p_user uuid, p_key text, p_ticket uuid, p_now timestamptz default now(), p_ads_limit integer default 10, p_shards integer default 25, p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_ads integer;
    v_t uuid;
    v_hit public.cards_idem%rowtype;
    v_out jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    if p_shards is null or p_shards < 1 or p_shards > 1000 then raise exception 'cards: source'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> 'ad' then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    v_ads := (r ->> 'ads_today')::integer;
    if v_ads >= p_ads_limit then raise exception 'cards: ad_limit'; end if;
    update public.cards_ad_tickets set used_at = p_now
     where id = p_ticket and user_id = p_user and used_at is null
       and issued_at <= p_now - interval '10 seconds' and issued_at >= p_now - interval '1 hour'
    returning id into v_t;
    if v_t is null then raise exception 'cards: ticket'; end if;
    update public.cards_wallets
       set stock = (r ->> 'stock')::integer, anchor = case when (r ->> 'paused')::boolean then p_now else (r ->> 'anchor')::timestamptz end,
           paris_day = v_today, ads_today = v_ads + 1, bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           shards = shards + p_shards, seen_at = p_now, version = version + 1, updated_at = p_now
     where user_id = p_user;
    v_out := jsonb_build_object('replayed', false, 'gained', p_shards, 'shards', w.shards + p_shards, 'ads_today', v_ads + 1);
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, 'ad', v_out, p_now);
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at) values (p_user, 'ad', p_key, jsonb_build_object('shards', p_shards), p_now);
    return v_out;
  end
  $f$;

  -- ---------- recycle ----------
  drop function if exists public.cards_recycle(uuid, timestamptz);
  -- p_n null: every extra copy (copies above 1) of the unlocked cards that are neither Gold nor Full Art; one copy of each card stays. p_n set: one
  -- extra copy of that card, any edition, never a locked card, never the last copy. Shards: Standard 1, Stage 2, Holo 5, Era 12, Gold 30, Full Art 80.
  create or replace function public.cards_recycle(p_user uuid, p_key text, p_n integer default null, p_now timestamptz default now(), p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_op text := 'recycle:' || coalesce(p_n::text, 'bulk');
    v_hit public.cards_idem%rowtype;
    v_recycled integer := 0;
    v_shards integer := 0;
    v_locked integer := 0;
    v_gold integer := 0;
    v_row record;
    v_out jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> v_op then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;

    if p_n is not null then
      select o.copies, o.locked, c.rarity into v_row from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and o.card_no = p_n;
      if not found then raise exception 'cards: notowned'; end if;
      if v_row.locked then raise exception 'cards: locked'; end if;
      if v_row.copies < 2 then raise exception 'cards: lastcopy'; end if;
      update public.cards_owned set copies = copies - 1 where user_id = p_user and card_no = p_n;
      v_recycled := 1;
      v_shards := case v_row.rarity when 'C' then 1 when 'U' then 2 when 'R' then 5 when 'SR' then 12 when 'UR' then 30 else 80 end;
    else
      select coalesce(sum(case when c.rarity in ('UR', 'L') then o.copies - 1 else 0 end), 0)::integer,
             coalesce(sum(case when c.rarity not in ('UR', 'L') and o.locked then o.copies - 1 else 0 end), 0)::integer
        into v_gold, v_locked
        from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and o.copies > 1;
      select coalesce(sum(o.copies - 1), 0)::integer,
             coalesce(sum((o.copies - 1) * case c.rarity when 'C' then 1 when 'U' then 2 when 'R' then 5 else 12 end), 0)::integer
        into v_recycled, v_shards
        from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no
       where o.user_id = p_user and o.copies > 1 and not o.locked and c.rarity not in ('UR', 'L');
      if v_recycled < 1 then raise exception 'cards: nothing'; end if;
      update public.cards_owned o set copies = 1
        from public.cards_catalog c
       where c.card_no = o.card_no and o.user_id = p_user and o.copies > 1 and not o.locked and c.rarity not in ('UR', 'L');
    end if;

    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    update public.cards_wallets
       set shards = shards + v_shards, stock = (r ->> 'stock')::integer, anchor = case when (r ->> 'paused')::boolean then p_now else (r ->> 'anchor')::timestamptz end,
           paris_day = v_today, ads_today = (r ->> 'ads_today')::integer, bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           seen_at = p_now, version = version + 1, updated_at = p_now
     where user_id = p_user;
    v_out := jsonb_build_object('replayed', false, 'recycled', v_recycled, 'shards', v_shards, 'shards_total', w.shards + v_shards,
                                'skipped', jsonb_build_object('locked', v_locked, 'goldAndFullArt', v_gold));
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, v_op, v_out, p_now);
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at) values (p_user, 'recycle', p_key, v_out, p_now);
    return v_out;
  end
  $f$;

  create or replace function public.cards_lock(p_user uuid, p_card_no integer, p_on boolean, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_n integer;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    update public.cards_owned set locked = coalesce(p_on, false) where user_id = p_user and card_no = p_card_no;
    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'cards: notowned'; end if;
    select count(*) into v_n from public.cards_owned where user_id = p_user and locked;
    return jsonb_build_object('n', p_card_no, 'locked', coalesce(p_on, false), 'locks', v_n);
  end
  $f$;

  create or replace function public.cards_seen(p_user uuid, p_cards integer[])
    returns integer
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_n integer;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_cards is not null and cardinality(p_cards) > 0 and cardinality(p_cards) <= 500 then
      update public.cards_owned set seen = true where user_id = p_user and card_no = any (p_cards) and not seen;
    end if;
    select count(*) into v_n from public.cards_owned where user_id = p_user and not seen;
    return v_n;
  end
  $f$;

  -- The quiet check. It accrues the packs the timer earned up to the pause, then restarts the timer from now. It takes nothing, whatever its state.
  create or replace function public.cards_still_there(p_user uuid, p_now timestamptz default now(), p_timer_cap integer default 40)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now, w.timer_today, p_timer_cap, 10, w.seen_at + interval '2 hours');
    update public.cards_wallets
       set stock = (r ->> 'stock')::integer, anchor = case when (r ->> 'paused')::boolean then p_now else (r ->> 'anchor')::timestamptz end,
           paris_day = v_today, ads_today = (r ->> 'ads_today')::integer, bonus_today = (r ->> 'bonus_today')::integer, timer_today = (r ->> 'timer_today')::integer,
           seen_at = p_now, version = version + 1, updated_at = p_now
     where user_id = p_user;
    return jsonb_build_object('ok', true, 'was_paused', (r ->> 'paused')::boolean);
  end
  $f$;

  -- ---------- grants ----------
  revoke all on function public.cards_theme_of(text) from public, anon, authenticated;
  revoke all on function public.cards_in_pool(integer, text, text) from public, anon, authenticated;
  revoke all on function public.cards_pool_has(text, text, text[]) from public, anon, authenticated;
  revoke all on function public.cards_daily_group(date) from public, anon, authenticated;
  revoke all on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer, integer, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_pity_count(uuid) from public, anon, authenticated;
  revoke all on function public.cards_wallet(uuid, timestamptz, integer, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_player(uuid, timestamptz, integer) from public, anon, authenticated;
  revoke all on function public.cards_open(uuid, text, text, text, text, jsonb, timestamptz, integer, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_craft(uuid, text, integer, timestamptz, integer) from public, anon, authenticated;
  revoke all on function public.cards_ad_grant(uuid, text, uuid, timestamptz, integer, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_recycle(uuid, text, integer, timestamptz, integer) from public, anon, authenticated;
  revoke all on function public.cards_lock(uuid, integer, boolean, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_seen(uuid, integer[]) from public, anon, authenticated;
  revoke all on function public.cards_still_there(uuid, timestamptz, integer) from public, anon, authenticated;
  grant execute on function public.cards_theme_of(text) to service_role;
  grant execute on function public.cards_in_pool(integer, text, text) to service_role;
  grant execute on function public.cards_pool_has(text, text, text[]) to service_role;
  grant execute on function public.cards_daily_group(date) to service_role;
  grant execute on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer, integer, timestamptz) to service_role;
  grant execute on function public.cards_pity_count(uuid) to service_role;
  grant execute on function public.cards_wallet(uuid, timestamptz, integer, integer, integer) to service_role;
  grant execute on function public.cards_player(uuid, timestamptz, integer) to service_role;
  grant execute on function public.cards_open(uuid, text, text, text, text, jsonb, timestamptz, integer, integer, integer) to service_role;
  grant execute on function public.cards_craft(uuid, text, integer, timestamptz, integer) to service_role;
  grant execute on function public.cards_ad_grant(uuid, text, uuid, timestamptz, integer, integer, integer) to service_role;
  grant execute on function public.cards_recycle(uuid, text, integer, timestamptz, integer) to service_role;
  grant execute on function public.cards_lock(uuid, integer, boolean, timestamptz) to service_role;
  grant execute on function public.cards_seen(uuid, integer[]) to service_role;
  grant execute on function public.cards_still_there(uuid, timestamptz, integer) to service_role;

  if (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_wallet') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_roll') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_open') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_craft') <> 1
     or (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_ad_grant') <> 1 then
    raise exception '110-core: cards_roll, cards_wallet, cards_open, cards_craft and cards_ad_grant must each exist once';
  end if;
  if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'cards_group_types' and not rowsecurity) then
    raise exception '110-core: cards_group_types has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name = 'cards_group_types' and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '110-core: cards_group_types is granted to a browser role';
  end if;

  notify pgrst, 'reload schema';
end $c110$;

-- ==== 11/15: 111-group-types.sql (verbatim) ====
-- 111-group-types.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; the type of each group, for the packs Girl groups and Boy groups)
--
-- What:   fills cards_group_types (created by 110) with the type of 41 groups: 24 girl groups, 16 boy groups, 1 mixed (a brother-sister duo), in ONE
--         DO block. A row is written only for a group that exists in cards_entities; the others are skipped silently.
-- Why:    the themed packs need to know whether a group is a girl group or a boy group, and no table of the cards or of the quiz site holds it
--         (groups has no gender; songs.gender is per song, not per group). Rather than invent it, each type below is a value that TWO
--         independent public sources gave, fetched on 2026-11-13: source_a is the English Wikipedia short description of the group's article, source_b is
--         either the Wikidata item's "instance of" (Q641066 girl group, Q216337 boy band) or the short description of the group's article in another
--         language Wikipedia (Korean, mostly). A group whose two sources do not both name a type is NOT in the file, so it belongs only to
--         "All idols", the pack of the day and the focus pack: day6 (English description: "rock band", no type) and team (the English article found
--         was another group; no type). They can be added when two sources agree.
-- Rows:   41 rows inserted or refreshed (checked_on 2026-11-13). Idempotent: a second run changes nothing.
-- Needs:  110 (cards_group_types) and the group entities of 101/103.
-- Verify: select gender, count(*) from public.cards_group_types group by gender order by gender;   expect boy 16, girl 24, mixed 1 (fewer when a group is not in the catalog yet)
-- Verify: select count(*) from public.cards_group_types t where not exists (select 1 from public.cards_entities e where e.id = t.entity_id and e.kind = 'group');   expect 0
-- Verify: select count(*) from public.cards_group_types where length(source_a) = 0 or length(source_b) = 0 or source_a = source_b;   expect 0
-- Undo:   111-group-types.rollback.sql (deletes these rows)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor).

do $c111$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_group_types') is null then
    raise exception '111-group-types: run 110-core.sql first';
  end if;

  insert into public.cards_group_types (entity_id, gender, source_a, source_b, checked_on)
  select e.id, v.gender, v.source_a, v.source_b, date '2026-11-13'
    from (values
      ('group:akmu', 'mixed', 'en.wikipedia.org short description "South Korean sibling duo" (AKMU)', 'ko.wikipedia.org short description "대한민국의 남매 음악 듀오"'),
      ('group:apink', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Apink)', 'Wikidata item Q483286, instance of Q641066 (girl group)'),
      ('group:artms', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Artms)', 'Wikidata item Q119692734, instance of Q641066 (girl group)'),
      ('group:astro', 'boy', 'en.wikipedia.org short description "South Korean boy band" (Astro (South Korean band))', 'Wikidata item Q23004252, instance of Q216337 (boy band)'),
      ('group:billlie', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Billlie)', 'Wikidata item Q108888399, instance of Q641066 (girl group)'),
      ('group:btob', 'boy', 'en.wikipedia.org short description "South Korean boy band" (BtoB (band))', 'ko.wikipedia.org short description "대한민국의 6인조 보이 그룹"'),
      ('group:cortis', 'boy', 'en.wikipedia.org short description "South Korean boy band" (Cortis)', 'Wikidata item Q135668928, instance of Q216337 (boy band)'),
      ('group:dreamcatcher', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Dreamcatcher (group))', 'ko.wikipedia.org short description "대한민국의 7인조 걸 그룹"'),
      ('group:fifty-fifty', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Fifty Fifty (group))', 'Wikidata item Q116731010, instance of Q641066 (girl group)'),
      ('group:fromis-9', 'girl', 'en.wikipedia.org short description "South Korean girl group" (Fromis 9)', 'Wikidata item Q41398331, instance of Q641066 (girl group)'),
