    ) as v(id, gender, source_a, source_b)
    join public.cards_entities e on e.id = v.id and e.kind = 'group'
  on conflict (entity_id) do update set gender = excluded.gender, source_a = excluded.source_a, source_b = excluded.source_b, checked_on = excluded.checked_on;
end $c111$;

-- ==== 12/15: 112-social.sql (verbatim) ====
-- 112-social.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; friends by one-time code, the ranking by completion, player pages, showcase and badges)
--
-- What:   in ONE DO block:
--           tables   cards_friend_codes   a one-time code a player makes to add a friend (8 characters, valid 24 hours, works once)
--                    cards_friends        a friendship, stored in both directions (at most 100 per player)
--           functions
--                    cards_friend_code_new(user, code, now)       replaces the player's unused code with a new one
--                    cards_friend_redeem(user, key, code, now)    uses a code: both players become friends; a failure is an answer, not an error
--                    cards_friend_remove(user, nickname)          ends a friendship (both directions)
--                    cards_friends(user)                          the friends with their completion and their wishlist
--                    cards_profile_of(user, viewer)               a player page: nickname, cards, showcase of 3, badges, the wishlist for friends
--                    cards_profile(viewer, nickname)              the same, found by nickname
--                    cards_ranking(user, scope, limit)            the ranking by completion ONLY: 'friends' (friends and himself) or 'all'
-- Why:    the prototype v6: Ranking by completion %, friends first, with each player's showcase of three starred cards and earned badges; friends
--         by one-time code, wishlists visible to friends, no chat; nicknames only (profiles.username, never an e-mail or a name). The ranking never
--         uses the number of packs opened. Cards a player holds are public only as his completion, his showcase and his badges.
-- Rows:   0 rows. 2 tables, 7 functions. Additive. No XP, level, streak or badge of kpopquiz.org is read or written (the badges here are the
--         cards' own: Founder, a complete group, First Gold, First Full Art, 100 cards).
-- Needs:  001, 105 (ledgers), 110 (created_at, locked) and the app's profiles table (username).
-- Notes:  a code failure (unknown, expired, used, your own, a full friend list, too many tries) is returned as {ok: false, error: ...} and the try
--         is counted: more than 8 tries in 10 minutes answer "rate". A player needs a nickname (a profiles row) to make or use a code.
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_friend_code_new', 'cards_friend_redeem', 'cards_friend_remove', 'cards_friends', 'cards_profile_of', 'cards_profile', 'cards_ranking');   expect 7
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname like 'cards\_%';   expect f
-- Verify: select count(*) from pg_tables where schemaname = 'public' and tablename in ('cards_friend_codes', 'cards_friends') and rowsecurity;   expect 2
-- Verify: select count(*) from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_friend_codes', 'cards_friends') and grantee in ('anon', 'authenticated');   expect 0
-- Undo:   112-social.rollback.sql (drops the 2 tables with their rows: friendships are not earned data)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c112$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.profiles') is null then
    raise exception '112-social: the profiles table is missing';
  end if;
  if to_regprocedure('public.cards_open(uuid, text, text, text, text, jsonb, timestamptz, integer, integer, integer)') is null then
    raise exception '112-social: run 110-core.sql first';
  end if;

  create table if not exists public.cards_friend_codes (
    code text constraint cards_friend_codes_pkey primary key constraint cards_friend_codes_code_check check (code ~ '^[0-9A-HJKMNP-TV-Z]{8}$'),
    user_id uuid not null constraint cards_friend_codes_user_id_fkey references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    expires_at timestamptz not null,
    used_at timestamptz,
    used_by uuid
  );
  alter table public.cards_friend_codes enable row level security;
  revoke all on table public.cards_friend_codes from public, anon, authenticated;
  grant all on table public.cards_friend_codes to service_role;
  create index if not exists cards_friend_codes_user_idx on public.cards_friend_codes (user_id, created_at desc);

  create table if not exists public.cards_friends (
    user_id uuid not null constraint cards_friends_user_id_fkey references auth.users(id) on delete cascade,
    friend_id uuid not null constraint cards_friends_friend_id_fkey references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    constraint cards_friends_pkey primary key (user_id, friend_id),
    constraint cards_friends_self_check check (user_id <> friend_id)
  );
  alter table public.cards_friends enable row level security;
  revoke all on table public.cards_friends from public, anon, authenticated;
  grant all on table public.cards_friends to service_role;

  -- A new code (made by the server with crypto.randomInt) replaces every unused code of the player.
  create or replace function public.cards_friend_code_new(p_user uuid, p_code text, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if not exists (select 1 from public.profiles where id = p_user) then raise exception 'cards: nickname'; end if;
    if p_code is null or p_code !~ '^[0-9A-HJKMNP-TV-Z]{8}$' then raise exception 'cards: code'; end if;
    delete from public.cards_friend_codes where user_id = p_user and used_at is null;
    insert into public.cards_friend_codes (code, user_id, created_at, expires_at) values (p_code, p_user, p_now, p_now + interval '24 hours');
    return jsonb_build_object('code', p_code, 'expires_at', p_now + interval '24 hours');
  end
  $f$;

  create or replace function public.cards_friend_redeem(p_user uuid, p_key text, p_code text, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_hit public.cards_idem%rowtype;
    v_code public.cards_friend_codes%rowtype;
    v_norm text := upper(regexp_replace(coalesce(p_code, ''), '[^0-9A-Za-z]', '', 'g'));
    v_tries integer;
    v_out jsonb;
    v_nick text;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_key is null or length(p_key) not between 8 and 64 then raise exception 'cards: key'; end if;
    if not exists (select 1 from public.profiles where id = p_user) then raise exception 'cards: nickname'; end if;
    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 10, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;
    select * into v_hit from public.cards_idem where user_id = p_user and idem_key = p_key;
    if found then
      if v_hit.op <> 'friend' then raise exception 'cards: idem_conflict'; end if;
      return v_hit.response || jsonb_build_object('replayed', true);
    end if;

    select count(*) into v_tries from public.cards_audit where user_id = p_user and kind = 'friend' and created_at > p_now - interval '10 minutes';
    if v_tries >= 8 then return jsonb_build_object('ok', false, 'error', 'rate'); end if;
    insert into public.cards_audit (user_id, kind, idem_key, detail, created_at) values (p_user, 'friend', p_key, jsonb_build_object('try', true), p_now);

    select * into v_code from public.cards_friend_codes where code = v_norm for update;
    if not found then return jsonb_build_object('ok', false, 'error', 'code_invalid'); end if;
    if v_code.used_at is not null then return jsonb_build_object('ok', false, 'error', 'code_used'); end if;
    if v_code.expires_at <= p_now then return jsonb_build_object('ok', false, 'error', 'code_expired'); end if;
    if v_code.user_id = p_user then return jsonb_build_object('ok', false, 'error', 'self'); end if;
    if exists (select 1 from public.cards_friends where user_id = p_user and friend_id = v_code.user_id) then return jsonb_build_object('ok', false, 'error', 'already'); end if;
    if (select count(*) from public.cards_friends where user_id = p_user) >= 100 or (select count(*) from public.cards_friends where user_id = v_code.user_id) >= 100 then
      return jsonb_build_object('ok', false, 'error', 'friend_limit');
    end if;
    update public.cards_friend_codes set used_at = p_now, used_by = p_user where code = v_norm;
    insert into public.cards_friends (user_id, friend_id, created_at) values (p_user, v_code.user_id, p_now), (v_code.user_id, p_user, p_now) on conflict do nothing;
    select username into v_nick from public.profiles where id = v_code.user_id;
    v_out := jsonb_build_object('ok', true, 'replayed', false, 'nickname', v_nick);
    insert into public.cards_idem (user_id, idem_key, op, response, created_at) values (p_user, p_key, 'friend', v_out, p_now);
    return v_out;
  end
  $f$;

  create or replace function public.cards_friend_remove(p_user uuid, p_nickname text)
    returns boolean
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_other uuid;
    n integer;
  begin
    select id into v_other from public.profiles where username = lower(coalesce(p_nickname, ''));
    if v_other is null then return false; end if;
    delete from public.cards_friends where (user_id = p_user and friend_id = v_other) or (user_id = v_other and friend_id = p_user);
    get diagnostics n = row_count;
    return n > 0;
  end
  $f$;

  -- A player page. The wishlist is returned for the player himself and for his friends only.
  create or replace function public.cards_profile_of(p_user uuid, p_viewer uuid)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    v_nick text;
    v_owned integer;
    v_created timestamptz;
    v_badges jsonb := '[]'::jsonb;
    v_show jsonb;
    v_friend boolean;
    v_me boolean := p_user = p_viewer;
    r record;
  begin
    select username into v_nick from public.profiles where id = p_user;
    if v_nick is null then return null; end if;
    select count(*) into v_owned from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and c.in_packs;
    select coalesce((select w.created_at from public.cards_wallets w where w.user_id = p_user), now()) into v_created;
    if v_created < timestamptz '2027-03-01 00:00+00' then v_badges := v_badges || to_jsonb('Founder'::text); end if;
    for r in select x.name from public.cards_goals_progress(p_user, null) x where x.kind = 'group' and x.total > 0 and x.owned >= x.total order by x.name loop
      v_badges := v_badges || to_jsonb(r.name || ' complete');
    end loop;
    if exists (select 1 from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and c.rarity = 'UR') then v_badges := v_badges || to_jsonb('First Gold'::text); end if;
    if exists (select 1 from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where o.user_id = p_user and c.rarity = 'L') then v_badges := v_badges || to_jsonb('First Full Art'::text); end if;
    if v_owned >= 100 then v_badges := v_badges || to_jsonb('100 cards'::text); end if;
    select coalesce(jsonb_agg(s.card_no), '[]'::jsonb) into v_show from (
      select o.card_no from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no
       where o.user_id = p_user and c.in_packs
       order by o.favorite desc, array_position(array['C', 'U', 'R', 'SR', 'UR', 'L'], c.rarity) desc, o.card_no limit 3) s;
    v_friend := exists (select 1 from public.cards_friends f where f.user_id = p_viewer and f.friend_id = p_user);
    return jsonb_build_object('nickname', v_nick, 'owned', v_owned, 'showcase', v_show, 'badges', v_badges, 'friend', v_friend, 'me', v_me,
      'wishlist', case when v_me or v_friend then coalesce((select jsonb_agg(x.card_no order by x.card_no) from public.cards_wishlist x where x.user_id = p_user), '[]'::jsonb) else null end);
  end
  $f$;

  create or replace function public.cards_profile(p_viewer uuid, p_nickname text)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    v_id uuid;
  begin
    select id into v_id from public.profiles where username = lower(coalesce(p_nickname, ''));
    if v_id is null then return null; end if;
    return public.cards_profile_of(v_id, p_viewer);
  end
  $f$;

  create or replace function public.cards_friends(p_user uuid)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    r record;
    v_out jsonb := '[]'::jsonb;
  begin
    for r in select f.friend_id from public.cards_friends f join public.profiles p on p.id = f.friend_id where f.user_id = p_user order by p.username loop
      v_out := v_out || jsonb_build_array(public.cards_profile_of(r.friend_id, p_user));
    end loop;
    return jsonb_build_object('friends', v_out,
      'code', (select jsonb_build_object('code', c.code, 'expires_at', c.expires_at) from public.cards_friend_codes c
                where c.user_id = p_user and c.used_at is null and c.expires_at > now() order by c.created_at desc limit 1));
  end
  $f$;

  -- The ranking, by the number of distinct cards owned (that is the completion) and then the nickname. Never by packs opened.
  create or replace function public.cards_ranking(p_user uuid, p_scope text, p_limit integer default 50)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    r record;
    v_out jsonb := '[]'::jsonb;
    v_ids uuid[];
    v_me jsonb;
    v_lim integer := greatest(1, least(coalesce(p_limit, 50), 100));
  begin
    if p_scope not in ('friends', 'all') then raise exception 'cards: scope'; end if;
    with counts as (
      select o.user_id, count(*)::integer as n from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no where c.in_packs group by o.user_id),
    pool as (
      select p.id, p.username, coalesce(c.n, 0) as n
        from public.profiles p left join counts c on c.user_id = p.id
       where (p_scope = 'all' and coalesce(c.n, 0) > 0)
          or (p_scope = 'friends' and (p.id = p_user or p.id in (select f.friend_id from public.cards_friends f where f.user_id = p_user)))),
    ranked as (select pool.*, row_number() over (order by pool.n desc, pool.username) as pos from pool)
    select array_agg(ranked.id order by ranked.pos) into v_ids from ranked where ranked.pos <= v_lim or ranked.id = p_user;
    for r in select x.id, row_number() over () as pos from unnest(coalesce(v_ids, '{}')) with ordinality as x(id, ord) order by x.ord loop
      v_me := public.cards_profile_of(r.id, p_user);
      if v_me is not null then v_out := v_out || jsonb_build_array(v_me); end if;
    end loop;
    return v_out;
  end
  $f$;

  revoke all on function public.cards_friend_code_new(uuid, text, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_friend_redeem(uuid, text, text, timestamptz) from public, anon, authenticated;
  revoke all on function public.cards_friend_remove(uuid, text) from public, anon, authenticated;
  revoke all on function public.cards_friends(uuid) from public, anon, authenticated;
  revoke all on function public.cards_profile_of(uuid, uuid) from public, anon, authenticated;
  revoke all on function public.cards_profile(uuid, text) from public, anon, authenticated;
  revoke all on function public.cards_ranking(uuid, text, integer) from public, anon, authenticated;
  grant execute on function public.cards_friend_code_new(uuid, text, timestamptz) to service_role;
  grant execute on function public.cards_friend_redeem(uuid, text, text, timestamptz) to service_role;
  grant execute on function public.cards_friend_remove(uuid, text) to service_role;
  grant execute on function public.cards_friends(uuid) to service_role;
  grant execute on function public.cards_profile_of(uuid, uuid) to service_role;
  grant execute on function public.cards_profile(uuid, text) to service_role;
  grant execute on function public.cards_ranking(uuid, text, integer) to service_role;

  if exists (select 1 from pg_tables where schemaname = 'public' and tablename in ('cards_friend_codes', 'cards_friends') and not rowsecurity) then
    raise exception '112-social: a new table has row level security off';
  end if;
  if exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name in ('cards_friend_codes', 'cards_friends') and grantee in ('anon', 'authenticated', 'PUBLIC')) then
    raise exception '112-social: a new table is granted to a browser role';
  end if;

  notify pgrst, 'reload schema';
end $c112$;

-- ==== 13/15: 113-moment.sql (verbatim) ====
-- 113-moment.sql (KpopCards lots 3 + 4 + 5, 2026-11-13; "The moment" of the card view: the event of the photo, the player's first copy, the quiz link)
--
-- What:   in ONE DO block:
--           column   cards_photos.event_precision   how much of event_date is known: 'day', 'month' or 'year' (null for no date); existing dates read as 'day'
--           function cards_moment(user, card_no)     the facts of one card in packs: the photo's event (name, date, precision), the player's first copy of it
--                                                    (when, in which of his packs, pack / craft / demo, copies) and the kpopquiz.org slug of its quiz page
-- Why:    lot 4 B3: the card view tells the moment the photo was taken (a null event hides the line), when and how the player got the card
--         ("Pulled on ..., pack 12" or "Crafted on ..."), and links to the idol's or the group's quiz on kpopquiz.org when that page exists.
-- Rows:   0 rows. 1 column, 1 function. Additive: the dates already stored are 'day' dates and keep reading as such.
-- Needs:  001 and 104 (cards_owned.first_pack_no, first_source). The quiz slug is read from public.groups when that table exists (the kpopquiz.org
--         groups, slug = the entity id after the colon); without it the slug is null and the link is hidden.
-- Errors: "cards: card" (not a card in packs), "cards: user".
-- Verify: select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'cards_photos' and column_name = 'event_precision';   expect 1
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_moment';   expect 1
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'cards_moment';   expect f
-- Undo:   113-moment.rollback.sql (drops the function and the column)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c113$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_photos') is null or to_regclass('public.cards_owned') is null then
    raise exception '113-moment: run 001-schema.sql first';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_owned' and column_name = 'first_pack_no') then
    raise exception '113-moment: run 104-economy.sql first';
  end if;

  alter table public.cards_photos add column if not exists event_precision text;
  if not exists (select 1 from pg_constraint where conname = 'cards_photos_event_precision_check' and conrelid = 'public.cards_photos'::regclass) then
    alter table public.cards_photos add constraint cards_photos_event_precision_check check (event_precision is null or event_precision in ('day', 'month', 'year'));
  end if;
  update public.cards_photos set event_precision = 'day' where event_date is not null and event_precision is null;

  create or replace function public.cards_moment(p_user uuid, p_card_no integer)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    c record;
    p record;
    o record;
    v_slug text;
    v_has_groups boolean := to_regclass('public.groups') is not null;
    v_idol text;
    v_group text;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    select k.card_no, k.entity_id, k.photo_id, e.kind, e.group_id into c
      from public.cards_catalog k join public.cards_entities e on e.id = k.entity_id
     where k.card_no = p_card_no and k.in_packs and e.active;
    if not found then raise exception 'cards: card'; end if;
    select ph.event_name, ph.event_date, ph.event_precision into p from public.cards_photos ph where ph.id = c.photo_id;
    select w.copies, w.first_at, w.first_pack_no, w.first_source into o from public.cards_owned w where w.user_id = p_user and w.card_no = p_card_no;
    -- The quiz page: the slug of the idol (or of the group itself) when a kpopquiz.org groups row has it, else the slug of its group.
    v_idol := regexp_replace(c.entity_id, '^[a-z]+:', '');
    v_group := case when c.group_id is null then null else regexp_replace(c.group_id, '^[a-z]+:', '') end;
    if v_has_groups then
      execute 'select slug from public.groups where slug = any ($1) order by (slug = $2) desc limit 1' into v_slug using array_remove(array[v_idol, v_group], null), v_idol;
    end if;
    return jsonb_build_object(
      'n', p_card_no,
      'event', case when p.event_name is null then null
                    else jsonb_build_object('name', p.event_name, 'date', p.event_date, 'precision', case when p.event_date is null then null else coalesce(p.event_precision, 'day') end) end,
      'yours', case when o.first_at is null then null
                    else jsonb_build_object('first_at', o.first_at, 'pack_no', o.first_pack_no, 'how', coalesce(o.first_source, 'pack'), 'copies', o.copies) end,
      'quiz_slug', v_slug);
  end
  $f$;

  revoke all on function public.cards_moment(uuid, integer) from public, anon, authenticated;
  grant execute on function public.cards_moment(uuid, integer) to service_role;

  notify pgrst, 'reload schema';
end $c113$;

-- ==== 14/15: 114-catalog-append.sql (verbatim) ====
-- 114-catalog-append.sql (KpopCards, 2026-11-14; the catalog must not freeze after the first pack)
--
-- What:   in ONE DO block, creates public.cards_catalog_append(p_dry_run boolean default true), the way to ADD cards once players hold cards.
--         cards_build_catalog() (103) refuses as soon as a card is owned or a pack opened, because it deletes and renumbers; this function never does:
--         1. it adds the new editions of the subjects that already have cards (a new approved photo opens the next free edition up the ladder)
--            and the new subjects (2 approved photos or more), with the SAME rules as cards_build_catalog(): one edition = one photo (a photo
--            already on a card is never used again), editions open from the bottom (C, U, R, SR, UR, L), the best photo of a new subject
--            on its highest edition, Stage takes the lowest rated stage photo, Full Art needs an honest 2x of the whole card (else it stays
--            locked "size"), a group gets a pair per edition (part 1 then part 2, consecutive numbers), a subject enters packs only from 2 photos;
--         2. the new cards are numbered after max(card_no), subjects in the order of cards_build_catalog() (sort_key, id), each one's
--            editions in ladder order. No existing row is updated, renumbered or deleted; cards_owned, cards_packs, cards_wallets and every
--            audit table are never read for writing. A second call adds 0 cards;
--         3. p_dry_run true (the default) only COUNTS and writes nothing: {dry_run, cards, subjects, new_subjects, extended_subjects, waiting,
--            from_no, to_no, by_rarity, not_shown}. Writing needs the explicit p_dry_run => false. The write takes a SHARE ROW EXCLUSIVE lock on
--            cards_catalog (reads and openings go on; a second append, a rebuild or any other writer waits), so two appends never share a number.
--         Writes only cards_catalog (new rows) and, for the subjects that received cards, cards_entities.active and lock_reasons.
-- Why:    the 18 subjects that wait for a second photo, and every photo approved after the first pack, could never enter the game.
-- Rows:   0 rows. 1 function. RLS unchanged (no policy added); execute for service_role only (the admin's server).
-- Needs:  001 to 003, 102 and 103 applied before (cards_build_catalog, the part and small_2x columns, the photo columns of lot 3).
-- Errors: "114-catalog-append: ..." at apply time when a table or file 103 is missing; at call time "cards_catalog_append: null" for a null
--         p_dry_run and a lock timeout (55P03, 5 s) when another writer holds cards_catalog.
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_catalog_append';   expect 1
-- Verify: select has_function_privilege('anon', 'public.cards_catalog_append(boolean)', 'execute') or has_function_privilege('authenticated', 'public.cards_catalog_append(boolean)', 'execute');   expect f
-- Verify: select has_function_privilege('service_role', 'public.cards_catalog_append(boolean)', 'execute');   expect t
-- Verify: select prosecdef and proconfig = array['search_path=public'] from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_catalog_append';   expect t
-- Verify: select public.cards_catalog_append(true) - 'by_rarity';   read-only preview (writes nothing); expect {"dry_run": true, "cards": N, "subjects": S, ...} with N = 0 while no photo is waiting
-- Verify: select min(card_no), max(card_no), count(*) from public.cards_catalog;   expect 1, N, N (contiguous; this file adds no card, only a call with false does)
-- Undo:   114-catalog-append.rollback.sql (drops the function; the cards it added stay, they are catalog rows like any other).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c114$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_catalog') is null or to_regclass('public.cards_photos') is null or to_regclass('public.cards_entities') is null then
    raise exception '114-catalog-append: the cards tables are missing (run 001 to 003 first)';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_catalog' and column_name = 'part')
     or not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_catalog' and column_name = 'small_2x') then
    raise exception '114-catalog-append: cards_catalog has no part or small_2x column (apply 102-catalog-rebuild.sql first)';
  end if;
  if to_regprocedure('public.cards_build_catalog()') is null
     or not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'cards_photos' and column_name = 'quality') then
    raise exception '114-catalog-append: cards_build_catalog() is missing (apply 103-catalog-photos.sql first)';
  end if;

  create or replace function public.cards_catalog_append(p_dry_run boolean default true)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    c_ladder constant text[] := array['C', 'U', 'R', 'SR', 'UR', 'L'];
    c_edition constant jsonb := '{"C": "std", "U": "stage", "R": "holo", "SR": "era", "UR": "gold", "L": "full"}'::jsonb;
    e record;
    v_ids bigint[];
    v_full boolean[];
    v_stage boolean[];
    v_cw integer[];
    v_shown boolean[];
    v_have text[];
    v_missing text[];
    v_open text[];
    v_pick jsonb;
    v_used bigint[];
    v_lock jsonb;
    v_old jsonb;
    v_final text[];
    v_k integer;
    v_i integer;
    v_j integer;
    v_r text;
    v_id bigint;
    v_cwi integer;
    v_base integer;
    v_no integer;
    v_cards integer := 0;
    v_subjects integer := 0;
    v_new integer := 0;
    v_ext integer := 0;
    v_waiting integer := 0;
    v_not_shown integer := 0;
    v_by jsonb := '{}'::jsonb;
    v_in boolean;
    v_size boolean;
  begin
    if p_dry_run is null then
      raise exception 'cards_catalog_append: null';
    end if;
    perform set_config('lock_timeout', '5s', true);
    if not p_dry_run then
      -- Two appends (or an append and a rebuild) never run together: the second waits here and then reads the first one's rows.
      lock table public.cards_catalog in share row exclusive mode;
    end if;
    select coalesce(max(card_no), 0) into v_base from public.cards_catalog;
    v_no := v_base;
    for e in select en.id, en.kind, en.lock_reasons from public.cards_entities en
              where en.kind in ('idol', 'group') and exists (select 1 from public.cards_photos p where p.entity_id = en.id)
              order by en.sort_key, en.id loop
      select coalesce(array_agg(distinct c.rarity), '{}'), coalesce(array_agg(c.photo_id) filter (where c.photo_id is not null), '{}')
        into v_have, v_used from public.cards_catalog c where c.entity_id = e.id;
      v_in := cardinality(v_have) > 0;
      -- The live photos no card uses yet, best first (the ranking of cards_build_catalog()).
      select array_agg(x.id order by x.rk), array_agg(x.full_ok order by x.rk), array_agg(x.stage order by x.rk),
             array_agg(x.cw order by x.rk), array_agg(x.shown order by x.rk)
        into v_ids, v_full, v_stage, v_cw, v_shown
        from (select p.id, p.stage, w.cw,
                     case when e.kind = 'group' then w.cw / 2 >= 640 else w.cw >= 640 end as full_ok,
                     (p.storage_path is not null or p.source_path is not null) as shown,
                     row_number() over (order by coalesce(p.quality, 3) desc, w.cw desc, p.event_date desc nulls last, p.slot) as rk
                from public.cards_photos p
                cross join lateral (select floor(least(p.source_width::numeric,
                                      p.source_height::numeric * (case when e.kind = 'group' then 11 else 5.5 end) / 8.5))::integer as cw) w
               where p.entity_id = e.id and p.status in ('auto', 'approved')
                 and p.source_width is not null and p.source_height is not null
                 and not (p.id = any (v_used))) x;
      -- The free editions, from the bottom: one per unused photo (a new subject: the whole ladder, and 2 photos at least).
      v_missing := array(select r from unnest(c_ladder) with ordinality as t(r, o) where not (r = any (v_have)) order by o);
      v_k := least(coalesce(cardinality(v_ids), 0), cardinality(v_missing));
      if v_k = 0 or (not v_in and v_k < 2) then
        if not v_in then v_waiting := v_waiting + 1; end if;
        continue;
      end if;
      v_open := v_missing[1:v_k];
      v_pick := '{}'::jsonb;
      v_used := '{}';
      v_size := false;
      if 'L' = any (v_open) then
        v_id := null;
        for v_i in 1 .. cardinality(v_ids) loop
          if v_full[v_i] then v_id := v_ids[v_i]; exit; end if;
        end loop;
        if v_id is null then
          v_open := array_remove(v_open, 'L');
          v_size := true;
        else
          v_pick := v_pick || jsonb_build_object('L', v_id);
          v_used := v_used || v_id;
        end if;
      end if;
      if 'U' = any (v_open) then
        v_id := null;
        for v_i in reverse cardinality(v_ids) .. 1 loop
          if v_stage[v_i] and not (v_ids[v_i] = any (v_used)) then v_id := v_ids[v_i]; exit; end if;
        end loop;
        if v_id is not null then
          v_pick := v_pick || jsonb_build_object('U', v_id);
          v_used := v_used || v_id;
        end if;
      end if;
      for v_i in reverse cardinality(v_open) .. 1 loop
        v_r := v_open[v_i];
        continue when v_pick ->> v_r is not null;
        v_id := null;
        for v_j in 1 .. cardinality(v_ids) loop
          if not (v_ids[v_j] = any (v_used)) then v_id := v_ids[v_j]; exit; end if;
        end loop;
        v_pick := v_pick || jsonb_build_object(v_r, v_id);
        v_used := v_used || v_id;
      end loop;
      v_final := v_have || v_open;
      v_old := coalesce(e.lock_reasons, '{}'::jsonb);
      v_lock := '{}'::jsonb;
      foreach v_r in array c_ladder loop
        if not (v_r = any (v_final)) then
          v_lock := v_lock || jsonb_build_object(v_r, case when v_old ->> v_r = 'hiatus' then 'hiatus' when v_r = 'L' and v_size then 'size' else 'photo' end);
        end if;
      end loop;
      if cardinality(v_open) = 0 then
        -- Only Full Art was free and no photo is large enough: no card to add, the reason is recorded on a write.
        if not p_dry_run and v_lock is distinct from v_old then
          update public.cards_entities set lock_reasons = v_lock where id = e.id;
        end if;
        continue;
      end if;
      foreach v_r in array v_open loop
        v_id := (v_pick ->> v_r)::bigint;
        v_i := array_position(v_ids, v_id);
        v_cwi := v_cw[v_i];
        if not p_dry_run then
          if e.kind = 'group' then
            insert into public.cards_catalog (card_no, num, entity_id, rarity, edition, photo_id, in_packs, part, small_2x)
            values (v_no + 1, 'BV1-' || lpad((v_no + 1)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 1, v_cwi / 2 < 640),
                   (v_no + 2, 'BV1-' || lpad((v_no + 2)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 2, (v_cwi - v_cwi / 2) < 640);
          else
            insert into public.cards_catalog (card_no, num, entity_id, rarity, edition, photo_id, in_packs, part, small_2x)
            values (v_no + 1, 'BV1-' || lpad((v_no + 1)::text, 4, '0'), e.id, v_r, c_edition ->> v_r, v_id, v_shown[v_i], 0, v_cwi < 640);
          end if;
        end if;
        v_j := case when e.kind = 'group' then 2 else 1 end;
        v_no := v_no + v_j;
        v_cards := v_cards + v_j;
        if not v_shown[v_i] then v_not_shown := v_not_shown + v_j; end if;
        v_by := jsonb_set(v_by, array[v_r], to_jsonb(coalesce((v_by ->> v_r)::integer, 0) + v_j));
      end loop;
      if not p_dry_run then
        update public.cards_entities set active = true, lock_reasons = v_lock where id = e.id;
      end if;
      v_subjects := v_subjects + 1;
      if v_in then v_ext := v_ext + 1; else v_new := v_new + 1; end if;
    end loop;
    return jsonb_build_object('dry_run', p_dry_run, 'cards', v_cards, 'subjects', v_subjects, 'new_subjects', v_new, 'extended_subjects', v_ext,
      'waiting', v_waiting, 'from_no', case when v_cards > 0 then v_base + 1 end, 'to_no', case when v_cards > 0 then v_no end,
      'by_rarity', v_by, 'not_shown', v_not_shown);
  end
  $f$;

  revoke all on function public.cards_catalog_append(boolean) from public, anon, authenticated;
  grant execute on function public.cards_catalog_append(boolean) to service_role;

  if has_function_privilege('anon', 'public.cards_catalog_append(boolean)', 'execute')
     or has_function_privilege('authenticated', 'public.cards_catalog_append(boolean)', 'execute') then
    raise exception '114-catalog-append: a browser role can execute cards_catalog_append';
  end if;

  notify pgrst, 'reload schema';
end $c114$;

-- ==== 15/15: 115-quiz-of-day-bonus.sql (verbatim) ====
-- 115-quiz-of-day-bonus.sql (KpopCards, run O1 lane c4q, 2026-11-14; the quiz of the day gives one pack; integrator rule, overrides decision 28)
--
-- What:   in ONE DO block:
--           constraint cards_bonus_earned_source_check   widened from ('quiz', 'kpopdle') to ('quiz', 'kpopdle', 'quiz_of_day')
--           index      cards_bonus_earned_quiz_day_key    unique (user_id, paris_day) where source = 'quiz_of_day': never two a Paris day, even in parallel
--           function   cards_bonus_record(user, now)      002's recording of the Kpopdle wins (unchanged) PLUS the quiz of the day: one row 'quiz_of_day' per
--                                                         Paris day for a signed-in player who finished the quiz that was the quiz of the day
--           function   cards_bonus_sync(user, now)        calls cards_bonus_record, returns jsonb {earned, quiz}: the bonus packs earned that Paris day and
--                                                         whether one of them is the quiz of the day (the lobby box reads it)
-- Why:    the integrator decided that finishing the quiz of the day gives +1 pack, counted inside CARDS_BONUS_PER_DAY (the cap does not move: 3 Kpopdle
--         wins and the quiz still open 3 packs), once per Paris day. The cards live on bunnyverse.org and the quiz on kpopquiz.org, so a cross-site call
--         is refused (403); the hub's server therefore records it itself (the lobby state and the opening of a bonus pack call these functions) and
--         no browser report is needed.
-- Rule:   a row is written for the player when a public.plays row of the player exists with all of:
--           player_id = the player (a guest has none, a Team account is refused by the server before this is called), total_questions > 0,
--           created_at on the Paris day of p_now and not after p_now (the play is stamped when it is finished: record_play inserts it at the end),
--           the quiz is published, is_quiz_of_the_day, and its quiz_of_the_day_date is the UTC date of the play (the date the site showed it as the
--           quiz of the day: the daily quiz is keyed by UTC date, the allowance by Paris date), and kpop's when quizzes.site_id exists.
--         The first such play of the Paris day is the one recorded. The key (source, play_ref) is 'quiz_of_day', 'quiz_of_day:<quiz date>:<player>':
--         the same quiz of the day gives a pack once to a player, so a replay across Paris midnight (the UTC date lags by 1 or 2 hours) gives nothing more.
-- Risk:   ACCEPTED BY THE INTEGRATOR. The completion is a score the browser reports: POST /api/quiz/[id]/play checks only 0 <= score <= max and
--         inserts the plays row through record_play, so a modified browser can post a play of the quiz of the day without playing it (decision 28 refused
--         the quiz of the day for that reason). The damage is bounded: at most one pack a Paris day, inside the cap of 3, and only for the quiz that was
--         the quiz of the day. A play of any other quiz, an anonymous play and a play of another player never count. Kpopdle wins stay decided in the
--         database (dle_guess) and are unchanged.
-- Rows:   0 rows at apply time. 1 constraint, 1 index, 2 functions (cards_bonus_record replaced: same signature, same return, same ACL).
-- Needs:  001 and 002. public.plays and public.quizzes (is_quiz_of_the_day, quiz_of_the_day_date, status) are read inside cards_bonus_record only and only
--         when they exist; public.dle_plays and public.dle_games (019) likewise. 110 and 104 need no change: they count the rows of cards_bonus_earned
--         through cards_bonus_plays, so the quiz row shares the cap with the Kpopdle rows and opens as source 'bonus'.
-- Errors: "cards: user" (null player), as before.
-- Verify: select pg_get_constraintdef(oid) from pg_constraint where conname = 'cards_bonus_earned_source_check' and conrelid = 'public.cards_bonus_earned'::regclass;   expect a check listing 'quiz', 'kpopdle' and 'quiz_of_day'
-- Verify: select count(*) from pg_indexes where schemaname = 'public' and indexname = 'cards_bonus_earned_quiz_day_key';   expect 1
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_bonus_record', 'cards_bonus_sync');   expect 2
-- Verify: select bool_or(has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('cards_bonus_record', 'cards_bonus_sync');   expect f
-- Verify: select bool_and(has_function_privilege('service_role', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('cards_bonus_record', 'cards_bonus_sync');   expect t
-- Verify: select prosecdef and 'search_path=public' = any (proconfig) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_bonus_sync';   expect t
-- Verify: select prosrc like '%is_quiz_of_the_day%' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'cards_bonus_record';   expect t (002's recording is replaced by the one that reads the quiz of the day; read only: no Verify line calls a function)
-- Undo:   115-quiz-of-day-bonus.rollback.sql (deletes the 'quiz_of_day' rows, narrows the check, restores 002's cards_bonus_record, drops the rest)
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $c115$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_bonus_earned') is null or to_regprocedure('public.cards_bonus_plays(uuid, date)') is null then
    raise exception '115-quiz-of-day-bonus: run 001-schema.sql and 002-functions.sql first';
  end if;

  -- The source check: replaced only when it does not list the new source yet.
  if not exists (select 1 from pg_constraint where conname = 'cards_bonus_earned_source_check' and conrelid = 'public.cards_bonus_earned'::regclass
                    and pg_get_constraintdef(oid) like '%quiz_of_day%') then
    alter table public.cards_bonus_earned drop constraint if exists cards_bonus_earned_source_check;
    alter table public.cards_bonus_earned add constraint cards_bonus_earned_source_check check (source in ('quiz', 'kpopdle', 'quiz_of_day'));
  end if;

  -- One quiz-of-the-day row a Paris day, whatever the quiz dates or the number of parallel calls.
  create unique index if not exists cards_bonus_earned_quiz_day_key on public.cards_bonus_earned (user_id, paris_day) where source = 'quiz_of_day';

  -- Records the bonus packs of the player's Paris day and returns how many were earned that day: the Kpopdle wins (one row per won play, decided in
  -- the database by dle_guess) and the quiz of the day (one row). Called by the hub's server (the lobby state, the opening of a bonus pack) and by
  -- POST /api/cards-bridge/bonus, after their own checks (session, Team account, flags).
  create or replace function public.cards_bonus_record(p_user uuid, p_now timestamptz default now())
    returns integer
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_from timestamptz := (v_today::timestamp at time zone 'Europe/Paris');
    v_to timestamptz := ((v_today + 1)::timestamp at time zone 'Europe/Paris');
    v_site boolean;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    -- A database without the daily games (019 not applied) records no Kpopdle win.
    if to_regclass('public.dle_plays') is not null and to_regclass('public.dle_games') is not null then
      insert into public.cards_bonus_earned (user_id, paris_day, source, play_ref, earned_at)
      select p_user, v_today, 'kpopdle', 'dle_plays:' || d.id::text, p_now
        from public.dle_plays d
       where d.game_id = any (array(select g.id from public.dle_games g where g.id like 'kpopdle%'))
         and d.play_date between v_today - 2 and v_today
         and d.user_id = p_user and d.status = 'won'
         and d.finished_at <= p_now and (d.finished_at at time zone 'Europe/Paris')::date = v_today
      on conflict on constraint cards_bonus_earned_play_key do nothing;
    end if;
    -- The quiz of the day: the first finished play of the Paris day on the quiz that was the quiz of the day (its UTC date is the play's UTC date).
    -- A database without the play tables records nothing. The partial unique index keeps one row a Paris day; the key one per quiz of the day (a quiz of
    -- the day that already gave its pack is skipped, so a replay of it never hides the play of the next one).
    if to_regclass('public.plays') is not null and to_regclass('public.quizzes') is not null then
      v_site := exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quizzes' and column_name = 'site_id');
      if v_site then
        insert into public.cards_bonus_earned (user_id, paris_day, source, play_ref, earned_at)
        select p_user, v_today, 'quiz_of_day', 'quiz_of_day:' || q.quiz_of_the_day_date::text || ':' || p_user::text, p_now
          from public.plays pl join public.quizzes q on q.id = pl.quiz_id
         where pl.player_id = p_user and pl.total_questions > 0
           and pl.created_at >= v_from and pl.created_at < v_to and pl.created_at <= p_now
           and q.is_quiz_of_the_day and q.status = 'published' and q.site_id = 'kpop'
           and q.quiz_of_the_day_date = (pl.created_at at time zone 'UTC')::date
           and not exists (select 1 from public.cards_bonus_earned e where e.source = 'quiz_of_day'
                            and e.play_ref = 'quiz_of_day:' || q.quiz_of_the_day_date::text || ':' || p_user::text)
         order by pl.created_at, pl.id
         limit 1
        on conflict do nothing;
      else
        insert into public.cards_bonus_earned (user_id, paris_day, source, play_ref, earned_at)
        select p_user, v_today, 'quiz_of_day', 'quiz_of_day:' || q.quiz_of_the_day_date::text || ':' || p_user::text, p_now
          from public.plays pl join public.quizzes q on q.id = pl.quiz_id
         where pl.player_id = p_user and pl.total_questions > 0
           and pl.created_at >= v_from and pl.created_at < v_to and pl.created_at <= p_now
           and q.is_quiz_of_the_day and q.status = 'published'
           and q.quiz_of_the_day_date = (pl.created_at at time zone 'UTC')::date
           and not exists (select 1 from public.cards_bonus_earned e where e.source = 'quiz_of_day'
                            and e.play_ref = 'quiz_of_day:' || q.quiz_of_the_day_date::text || ':' || p_user::text)
         order by pl.created_at, pl.id
         limit 1
        on conflict do nothing;
      end if;
    end if;
    return public.cards_bonus_plays(p_user, v_today);
  end
  $f$;

  -- The lobby read: records, then tells the bonus packs earned that Paris day and whether the quiz of the day is one of them.
  create or replace function public.cards_bonus_sync(p_user uuid, p_now timestamptz default now())
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_earned integer;
  begin
    v_earned := public.cards_bonus_record(p_user, p_now);
    return jsonb_build_object('earned', v_earned,
      'quiz', exists (select 1 from public.cards_bonus_earned where user_id = p_user and paris_day = v_today and source = 'quiz_of_day'));
  end
  $f$;

  revoke all on function public.cards_bonus_record(uuid, timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_bonus_record(uuid, timestamptz) to service_role;
  revoke all on function public.cards_bonus_sync(uuid, timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_bonus_sync(uuid, timestamptz) to service_role;

  notify pgrst, 'reload schema';
end $c115$;

commit;
